  beni: { bg: 'var(--accent-bg)', color: 'var(--accent)', border: 'var(--accent-border)' },
  kon:  { bg: 'var(--kon-bg)', color: 'var(--kon-lt)', border: 'var(--kon-border)' },
  matcha: { bg: 'var(--matcha-bg)', color: 'var(--matcha)', border: 'var(--matcha-border)' },
