    if (totalChars >= 800 && sceneCount >= 5) { pts++; reasons.push('構成の密度と複雑さ（' + sceneCount + 'シーン/' + totalChars.toLocaleString() + '字）'); }
    if (hasUniqueStructure) reasons.push('独自の構造・視点技法（回想・複線等）の使用');
    if (hasParadox) reasons.push('逆説・皮肉の活用（テーマ的奥行き）');
