    if (poeticCount >= 2) { pts = Math.min(5, pts + 1); reasons.push('詩的・文学的表現（作家性の発露）'); }
    if (!hasVaguePlaceholders && totalChars > 200) reasons.push('固有名詞・具体的描写で世界を構築');
