function analyzeDialogue() {
  const dialogue = document.getElementById('dc-dialogue')?.value.trim();
  const charName = document.getElementById('dc-char-name')?.value.trim() || 'キャラクター';
  const tone = document.getElementById('dc-tone')?.value;
  const context = document.getElementById('dc-context')?.value.trim();
  if (!dialogue) { toast('セリフを入力してください', 'error'); return; }

  const checks = [
    { id:'len', label:'長さ', icon:'fa-ruler', desc:'1台詞あたりの適切な長さ',
      check: () => { const lines = dialogue.split('\n').filter(Boolean); const maxL = Math.max(...lines.map(l=>l.length)); return maxL <= 60 ? { pass:true, note:'適切な長さです' } : { pass:false, note:`${maxL}文字。1行60字以下が目安。分割を検討してください。` }; }
    },
    { id:'label', label:'感情ラベリング', icon:'fa-face-meh', desc:'感情を直接言っていないか',
      check: () => { const bad = ['悲しい','嬉しい','怖い','辛い','幸せ','寂しい','怒っている']; const found = bad.filter(w => dialogue.includes(w)); return found.length===0 ? { pass:true, note:'感情のラベリングなし（良好）' } : { pass:false, note:`「${found.join('・')}」を使用。感情は行動・言い回しで見せましょう。` }; }
    },
    { id:'explain', label:'説明過多', icon:'fa-scroll', desc:'テーマや状況を直接説明していないか',
      check: () => { const p = ['つまり','要するに','ということは','だから言っているんだ','結局のところ']; const f = p.filter(w=>dialogue.includes(w)); return f.length===0 ? { pass:true, note:'説明過多なし（良好）' } : { pass:false, note:`「${f.join('・')}」は説明的すぎる傾向があります。` }; }
    },
    { id:'onomatop', label:'語尾のバリエーション', icon:'fa-shuffle', desc:'語尾が単調でないか',
      check: () => { const ends = dialogue.replace(/」/g,'').split(/[。…！？\n]/).filter(Boolean).map(l=>l.slice(-2)); const uniq = new Set(ends); return uniq.size >= Math.min(2, ends.length) ? { pass:true, note:'語尾に変化あり（良好）' } : { pass:false, note:'語尾が単調かもしれません。リズムを変えてみましょう。' }; }
    },
    { id:'subtext', label:'サブテキスト', icon:'fa-comment-dots', desc:'言外の意味・裏の意図があるか',
      check: () => { const words = dialogue.length; const q = (dialogue.match(/[…。]/g)||[]).length; const score = q/Math.max(words,1); return q >= 1 || context ? { pass:true, note:'含みや余白が感じられます' } : { pass:false, note:'もう少し「言わない」部分を増やすとサブテキストが生まれます。' }; }
    },
    { id:'character', label:'キャラクター性', icon:'fa-user', desc:'このキャラクターらしさがあるか',
      check: () => { const n = charName !== 'キャラクター'; return n ? { pass:true, note:`${charName}のセリフとして記録しました。声の個性を意識しましょう。` } : { pass:'warn', note:'キャラクター名が未入力です。名前を入れると一貫性チェックがしやすくなります。' }; }
    },
    { id:'repeat', label:'繰り返し', icon:'fa-copy', desc:'同じ言葉の繰り返しがないか',
      check: () => { const ws = dialogue.replace(/[「」、。！？…\n]/g,' ').split(/\s+/).filter(w=>w.length>=2); const cnt = {}; ws.forEach(w=>cnt[w]=(cnt[w]||0)+1); const dup = Object.entries(cnt).filter(([w,c])=>c>=2).map(([w])=>w); return dup.length===0 ? { pass:true, note:'不要な繰り返しなし（良好）' } : { pass:false, note:`「${dup.join('・')}」が複数回出現。意図的でなければ削除を。` }; }
    },
    { id:'question', label:'余白・間', icon:'fa-ellipsis', desc:'沈黙・間・余白があるか',
      check: () => { const has = /[…。\u3002]{2,}|（沈黙|（間|（ポーズ/.test(dialogue); return has ? { pass:true, note:'間・余白の表現があります' } : { pass:'warn', note:'「……」や「（沈黙）」などで間を演出すると効果的な場合があります。' }; }
    },
  ];

  const results = checks.map(c => ({ ...c, result: c.check() }));
  const passCount = results.filter(r => r.result.pass === true).length;
  const warnCount = results.filter(r => r.result.pass === 'warn').length;
  const failCount = results.filter(r => r.result.pass === false).length;
  const score = Math.round((passCount + warnCount * 0.5) / results.length * 100);
  const scoreColor = score >= 80 ? 'var(--matcha)' : score >= 60 ? 'var(--kogane)' : 'var(--accent)';
  const scoreLabel = score >= 80 ? '優秀' : score >= 60 ? '良好' : '要改善';

  const scoreBar = `
  <div style="display:flex;align-items:center;gap:16px;padding:14px 18px;background:var(--bg-subtle);border-radius:var(--radius-md);border:1px solid var(--border)">
    <div style="width:60px;height:60px;border-radius:50%;background:var(--bg-card);border:3px solid ${scoreColor};display:flex;align-items:center;justify-content:center;flex-direction:column;flex-shrink:0">
      <div style="font-size:18px;font-weight:800;color:${scoreColor}">${score}</div>
      <div style="font-size:9px;color:var(--text-muted)">点</div>
    </div>
    <div style="flex:1">
      <div style="font-size:15px;font-weight:700;color:${scoreColor};margin-bottom:4px">${scoreLabel}</div>
      <div style="display:flex;gap:12px;font-size:12px">
        <span style="color:var(--matcha)"><i class="fas fa-check-circle"></i> 合格 ${passCount}</span>
        <span style="color:var(--kogane)"><i class="fas fa-exclamation-circle"></i> 注意 ${warnCount}</span>
        <span style="color:var(--accent)"><i class="fas fa-times-circle"></i> 要修正 ${failCount}</span>
      </div>
      <div style="margin-top:6px;height:5px;background:var(--bg-hover);border-radius:3px;overflow:hidden">
        <div style="height:100%;width:${score}%;background:${scoreColor};border-radius:3px;transition:width .6s ease"></div>
      </div>
    </div>
  </div>`;

  const items = results.map(r => {
    const status = r.result.pass === true ? { icon:'fa-check-circle', color:'var(--matcha)', bg:'var(--matcha-bg)', border:'var(--matcha-border)' }
      : r.result.pass === 'warn' ? { icon:'fa-exclamation-circle', color:'var(--kogane)', bg:'var(--kogane-bg)', border:'var(--kogane-border)' }
      : { icon:'fa-times-circle', color:'var(--accent)', bg:'var(--accent-bg)', border:'var(--accent-border)' };
    return `
    <div style="padding:10px 12px;background:${status.bg};border:1px solid ${status.border};border-radius:var(--radius-md)">
      <div style="display:flex;align-items:center;gap:7px;margin-bottom:4px">
        <i class="fas ${status.icon}" style="color:${status.color};font-size:13px"></i>
        <span style="font-size:12.5px;font-weight:700;color:var(--text-primary)">${r.label}</span>
      </div>
      <div style="font-size:11.5px;color:var(--text-secondary);line-height:1.6">${r.result.note}</div>
    </div>`;
  }).join('');

  // 改善アドバイス
  const advices = [];
  if (failCount === 0 && warnCount === 0) advices.push('🏆 すべての診断項目をクリアしました！このセリフは高品質です。声に出して読んで最終確認しましょう。');
  if (results.find(r=>r.id==='label' && r.result.pass===false)) advices.push('💡 <strong>感情を見せる</strong>: 「悲しい」→「…もう笑えない」のように、状態ではなく言動でキャラクターの感情を伝えましょう。');
  if (results.find(r=>r.id==='subtext' && r.result.pass!==true)) advices.push('💡 <strong>サブテキスト</strong>: 本音を言わせず、行間に意味を隠しましょう。「愛してる」より「なんで……こんなとこまで来たんだ」の方が深みが出ます。');
  if (results.find(r=>r.id==='len' && r.result.pass===false)) advices.push('💡 <strong>セリフの分割</strong>: 長いセリフは他のキャラクターのリアクションや間で分割すると、テンポが生まれます。');
  if (results.find(r=>r.id==='explain' && r.result.pass===false)) advices.push('💡 <strong>説明を削る</strong>: 観客に説明するのではなく、シーンで体験させましょう。登場人物は知っている情報を「説明」しません。');
  if (tone === 'tense' && !dialogue.includes('…')) advices.push('💡 <strong>緊張シーンのテクニック</strong>: 緊張場面では短いセリフ・沈黙・「……」を多用すると心拍数が上がります。');
  if (advices.length === 0) advices.push('📝 このセリフは概ね良好です。次は声に出して読み、自然さを確認しましょう。');

  document.getElementById('dc-score-bar').innerHTML = scoreBar;
  document.getElementById('dc-items-grid').innerHTML = items;
  document.getElementById('dc-advice').innerHTML = advices.join('<br><br>');
  document.getElementById('dc-results').style.display = 'block';
  document.getElementById('dc-results').scrollIntoView({ behavior:'smooth', block:'start' });
}

// ── 新ツール: プロット穴探し ──────────────────────────────────
function renderToolPlotHoles() {
  return `
  <div class="page-header">
    <button class="btn btn-ghost btn-sm" onclick="navigate('tools')"><i class="fas fa-arrow-left"></i> ツール一覧</button>
  </div>
  <div style="background:linear-gradient(135deg,var(--accent-bg),var(--bg-subtle));border:1px solid var(--accent-border);border-radius:var(--radius-lg);padding:22px 26px;margin-bottom:22px;position:relative;overflow:hidden">
    <div style="position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:70px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--accent);opacity:0.07;pointer-events:none">穴</div>
    <div style="width:28px;height:2.5px;background:linear-gradient(90deg,var(--accent),var(--kogane));border-radius:2px;margin-bottom:10px"></div>
    <div style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin-bottom:5px">
      <i class="fas fa-magnifying-glass" style="color:var(--accent);margin-right:8px"></i>プロット穴探し
    </div>
    <div style="font-size:13px;color:var(--text-muted)">物語の構造を入力して論理矛盾・伏線未回収・動機不備を自動検出します。</div>
  </div>

  <div class="card" style="margin-bottom:16px">
    <div style="font-size:13px;font-weight:700;color:var(--text-primary);margin-bottom:14px;font-family:'Noto Serif JP',serif">
      <i class="fas fa-layer-group" style="color:var(--accent);margin-right:7px"></i>物語の骨格を入力
    </div>
    <div style="display:grid;gap:14px">
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">主人公の目標（何を達成しようとしているか）<span style="color:var(--accent)">*</span></div>
        <input class="form-input" id="ph-goal" placeholder="例: 失踪した妹を見つけ出す" style="font-size:13px">
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">主な障害・敵役（何が妨げているか）</div>
        <input class="form-input" id="ph-obstacle" placeholder="例: 組織に追われている・妹は死んでいると思っている" style="font-size:13px">
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">Act 1 の終わり（転換点1）</div>
        <textarea class="form-input" id="ph-act1" rows="2" placeholder="例: 妹から暗号メッセージを受け取り、追われる立場になる" style="font-size:13px;resize:vertical"></textarea>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">ミッドポイント（中盤の転換）</div>
        <textarea class="form-input" id="ph-mid" rows="2" placeholder="例: 協力者が組織の人間だと判明、信頼関係が崩れる" style="font-size:13px;resize:vertical"></textarea>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">クライマックス（最終対決）</div>
        <textarea class="form-input" id="ph-climax" rows="2" placeholder="例: 組織のアジトに単身乗り込み、妹を救出" style="font-size:13px;resize:vertical"></textarea>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">伏線リスト（張った伏線をカンマ区切りで）</div>
        <textarea class="form-input" id="ph-foreshadow" rows="2" placeholder="例: 協力者の左手首の傷、妹が残したメモ、謎の写真" style="font-size:13px;resize:vertical"></textarea>
      </div>
      <div>
        <div style="font-size:11px;color:var(--text-muted);margin-bottom:5px;font-weight:600">回収した伏線（カンマ区切りで）</div>
        <input class="form-input" id="ph-resolved" placeholder="例: 協力者の左手首の傷、謎の写真" style="font-size:13px">
      </div>
    </div>
    <button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="analyzePlotHoles()">
      <i class="fas fa-magnifying-glass"></i> プロット穴を検出する
    </button>
  </div>

  <div id="ph-results" style="display:none"></div>`;
}

function analyzePlotHoles() {
  const goal = document.getElementById('ph-goal')?.value.trim();
  const obstacle = document.getElementById('ph-obstacle')?.value.trim();
  const act1 = document.getElementById('ph-act1')?.value.trim();
  const mid = document.getElementById('ph-mid')?.value.trim();
  const climax = document.getElementById('ph-climax')?.value.trim();
  const foreshadowRaw = document.getElementById('ph-foreshadow')?.value.trim();
  const resolvedRaw = document.getElementById('ph-resolved')?.value.trim();
  if (!goal) { toast('主人公の目標を入力してください', 'error'); return; }

  const foreshadows = foreshadowRaw ? foreshadowRaw.split(/[,、，]/).map(s=>s.trim()).filter(Boolean) : [];
  const resolved = resolvedRaw ? resolvedRaw.split(/[,、，]/).map(s=>s.trim()).filter(Boolean) : [];
  const unresolved = foreshadows.filter(f => !resolved.some(r => r.includes(f.slice(0,4)) || f.includes(r.slice(0,4))));

  const issues = [];
  const warnings = [];
  const ok = [];

  // 目標チェック
  if (goal.length < 8) issues.push({ title:'目標が漠然としている', desc:'主人公の目標は具体的で測定可能なものにしましょう。「何を、いつまでに達成するか」が明確であるほど物語の推進力が増します。' });
  else ok.push({ title:'目標が設定されている', desc:`「${goal}」という明確な目標があります。` });

  // 障害チェック
  if (!obstacle) warnings.push({ title:'障害・敵役の記述なし', desc:'主人公の目標を妨げる障害や対立が明記されていません。強い障害がないと物語は弛緩します。' });
  else ok.push({ title:'障害が設定されている', desc:'目標に対する対立構造があります。' });

  // 構造チェック
  if (!act1) warnings.push({ title:'Act1終了（転換点）が未記入', desc:'転換点1がないと物語が一本調子になります。主人公が「引き返せない選択」をする瞬間を設けましょう。' });
  else ok.push({ title:'転換点1が設定されている', desc:'' });
  if (!mid) warnings.push({ title:'ミッドポイントが未記入', desc:'ミッドポイントがないとAct2が間延びしやすくなります。主人公の目標・認識が変わる中間点を設けましょう。' });
  else ok.push({ title:'ミッドポイントが設定されている', desc:'' });
  if (!climax) issues.push({ title:'クライマックスが未記入', desc:'クライマックスは物語の「証明」です。主人公が変化したことを行動で示す最終対決を明確にしましょう。' });
  else ok.push({ title:'クライマックスが設定されている', desc:'' });

  // 伏線チェック
  if (foreshadows.length === 0) warnings.push({ title:'伏線が記録されていない', desc:'伏線と回収は物語に必然性を生みます。重要な設定・小道具・セリフを伏線リストで管理しましょう。' });
  else if (unresolved.length > 0) {
    issues.push({ title:`未回収の伏線: ${unresolved.length}件`, desc:`「${unresolved.join('・')}」が回収されていないようです。意図的でなければ物語の穴になります。` });
  } else {
    ok.push({ title:'全伏線が回収されている', desc:`${foreshadows.length}件の伏線がすべて回収されています。` });
  }

  // クライマックスと目標の整合
  if (climax && goal && !climax.includes(goal.slice(0,4)) && !goal.includes(climax.slice(0,4))) {
    warnings.push({ title:'クライマックスと目標の整合を確認', desc:`目標「${goal.slice(0,15)}…」とクライマックスの直接的なつながりが見えにくいかもしれません。目標の達成/失敗がクライマックスで明確に示されているか確認しましょう。` });
  }

  const totalIssues = issues.length;
  const totalWarnings = warnings.length;
  const healthScore = Math.max(0, 100 - totalIssues * 20 - totalWarnings * 8);
  const healthColor = healthScore >= 80 ? 'var(--matcha)' : healthScore >= 60 ? 'var(--kogane)' : 'var(--accent)';

  const makeItems = (arr, type) => arr.map(item => {
    const s = type === 'issue' ? { icon:'fa-circle-xmark', color:'var(--accent)', bg:'var(--accent-bg)', border:'var(--accent-border)' }
      : type === 'warn' ? { icon:'fa-triangle-exclamation', color:'var(--kogane)', bg:'var(--kogane-bg)', border:'var(--kogane-border)' }
      : { icon:'fa-circle-check', color:'var(--matcha)', bg:'var(--matcha-bg)', border:'var(--matcha-border)' };
    return `<div style="padding:12px 14px;background:${s.bg};border:1px solid ${s.border};border-radius:var(--radius-md);margin-bottom:8px">
      <div style="display:flex;align-items:center;gap:7px;margin-bottom:4px">
        <i class="fas ${s.icon}" style="color:${s.color}"></i>
        <span style="font-size:13px;font-weight:700;color:var(--text-primary)">${item.title}</span>
      </div>
      ${item.desc ? `<div style="font-size:12px;color:var(--text-secondary);line-height:1.7;padding-left:20px">${item.desc}</div>` : ''}
    </div>`;
  }).join('');

  const html = `
  <div class="card" style="border-top:3px solid ${healthColor};margin-bottom:16px">
    <div style="display:flex;align-items:center;gap:14px;margin-bottom:18px">
      <div style="width:64px;height:64px;border-radius:50%;background:var(--bg-subtle);border:3px solid ${healthColor};display:flex;align-items:center;justify-content:center;flex-direction:column;flex-shrink:0">
        <div style="font-size:20px;font-weight:800;color:${healthColor}">${healthScore}</div>
        <div style="font-size:9px;color:var(--text-muted)">健全度</div>
      </div>
      <div>
        <div style="font-size:16px;font-weight:700;color:${healthColor};margin-bottom:4px">${healthScore >= 80 ? '物語構造は健全です' : healthScore >= 60 ? '一部要修正' : '重大な穴があります'}</div>
        <div style="font-size:12px;color:var(--text-muted)">問題 ${totalIssues}件 / 注意 ${totalWarnings}件 / 良好 ${ok.length}件</div>
      </div>
    </div>
    ${totalIssues > 0 ? `<div style="font-size:12.5px;font-weight:700;color:var(--accent);margin-bottom:8px;border-bottom:1px solid var(--border);padding-bottom:6px"><i class="fas fa-circle-xmark"></i> 重大な問題 (${totalIssues})</div>${makeItems(issues,'issue')}` : ''}
    ${totalWarnings > 0 ? `<div style="font-size:12.5px;font-weight:700;color:var(--kogane);margin-bottom:8px;border-bottom:1px solid var(--border);padding-bottom:6px;margin-top:${totalIssues>0?12:0}px"><i class="fas fa-triangle-exclamation"></i> 注意事項 (${totalWarnings})</div>${makeItems(warnings,'warn')}` : ''}
    ${ok.length > 0 ? `<div style="font-size:12.5px;font-weight:700;color:var(--matcha);margin-bottom:8px;border-bottom:1px solid var(--border);padding-bottom:6px;margin-top:12px"><i class="fas fa-circle-check"></i> 良好な点 (${ok.length})</div>${makeItems(ok,'ok')}` : ''}
  </div>`;

  document.getElementById('ph-results').innerHTML = html;
  document.getElementById('ph-results').style.display = 'block';
  document.getElementById('ph-results').scrollIntoView({ behavior:'smooth', block:'start' });
}

// ── 新ツール: ビートカウンター (Save the Cat) ────────────────────
function renderToolBeatCounter() {
  const beats = DB.get('sl_beat_counter', {});
  const BEAT_LIST = [
    { id:'opening', name:'オープニングイメージ', pct:1, color:'var(--kon-lt)', desc:'物語の最初の印象。世界の状態を示す「静止画」' },
    { id:'theme', name:'テーマの提示', pct:5, color:'var(--fuji)', desc:'主人公が聞き流す、物語のテーマとなる一言' },
    { id:'setup', name:'設定', pct:10, color:'var(--fuji)', desc:'世界・主人公・友人・日常を紹介する' },
    { id:'catalyst', name:'触媒・発端', pct:12, color:'var(--accent)', desc:'主人公の日常を変える出来事' },
    { id:'debate', name:'議論', pct:25, color:'var(--kogane)', desc:'変化への恐れ。行くべきか留まるべきか' },
    { id:'act2start', name:'第二幕への突入', pct:25, color:'var(--accent)', desc:'主人公が選択し新世界へ踏み出す' },
    { id:'bstory', name:'Bストーリー開始', pct:30, color:'var(--momo)', desc:'サブプロット（恋愛・友情）の始まり。テーマの体現者' },
    { id:'fun', name:'楽しみと遊び', pct:50, color:'var(--matcha)', desc:'新世界での活動。映画の「予告編要素」' },
    { id:'midpoint', name:'ミッドポイント', pct:50, color:'var(--accent)', desc:'主人公が「これが欲しい」と認識する転換点' },
    { id:'badguys', name:'悪役の迫来', pct:75, color:'var(--accent)', desc:'敵が反撃。主人公への圧力が増す' },
    { id:'allis', name:'すべてを失う', pct:75, color:'var(--accent)', desc:'主人公が最低点に。すべてが崩壊する瞬間' },
    { id:'dark', name:'暗闇の魂', pct:85, color:'var(--fuji)', desc:'すべてを失った後の省察・再起のための沈黙' },
    { id:'finalact', name:'第三幕への突入', pct:85, color:'var(--accent)', desc:'クライマックスに向けた行動開始' },
    { id:'climax', name:'クライマックス', pct:99, color:'var(--accent)', desc:'主人公が変化を証明する最終対決' },
    { id:'closing', name:'クロージングイメージ', pct:100, color:'var(--kon-lt)', desc:'オープニングイメージの対になる「新しい世界」の静止画' },
  ];

  const completedCount = BEAT_LIST.filter(b => beats[b.id]?.completed).length;
  const pct = Math.round(completedCount / BEAT_LIST.length * 100);

  const beatItems = BEAT_LIST.map((b, i) => {
    const done = beats[b.id]?.completed;
    const note = beats[b.id]?.note || '';
    return `
    <div style="padding:12px 14px;background:${done ? 'var(--matcha-bg)' : 'var(--bg-subtle)'};border:1px solid ${done ? 'var(--matcha-border)' : 'var(--border)'};border-radius:var(--radius-md);margin-bottom:8px;transition:all .2s">
      <div style="display:flex;align-items:flex-start;gap:10px">
        <div style="display:flex;align-items:center;gap:8px;flex:1">
          <input type="checkbox" id="beat-cb-${b.id}" ${done ? 'checked' : ''} onchange="toggleBeat('${b.id}')" style="width:16px;height:16px;accent-color:var(--matcha);flex-shrink:0;margin-top:2px">
          <div style="flex:1">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
              <span style="font-size:11px;background:${b.color}22;color:${b.color};padding:1px 7px;border-radius:var(--radius-full);font-weight:700">${i+1}</span>
              <span style="font-size:13.5px;font-weight:${done?'600':'700'};color:${done?'var(--text-muted)':'var(--text-primary)'};text-decoration:${done?'line-through':''}">${b.name}</span>
              <span style="font-size:10px;color:var(--text-muted)">p.${b.pct}</span>
            </div>
            <div style="font-size:11.5px;color:var(--text-muted);margin-top:2px;padding-left:24px">${b.desc}</div>
            <input class="form-input" style="margin-top:6px;padding-left:24px;font-size:11.5px;height:30px;background:transparent;border-color:${done?'var(--matcha-border)':'var(--border)'}" placeholder="メモ（シーン番号、ページ数など）" value="${esc(note)}" oninput="saveBeatNote('${b.id}',this.value)">
          </div>
        </div>
      </div>
    </div>`;
  }).join('');

  return `
  <div class="page-header">
    <button class="btn btn-ghost btn-sm" onclick="navigate('tools')"><i class="fas fa-arrow-left"></i> ツール一覧</button>
  </div>
  <div style="background:linear-gradient(135deg,var(--kogane-bg),var(--bg-subtle));border:1px solid var(--kogane-border);border-radius:var(--radius-lg);padding:22px 26px;margin-bottom:22px;position:relative;overflow:hidden">
    <div style="position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:70px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--kogane);opacity:0.07;pointer-events:none">ビ</div>
    <div style="width:28px;height:2.5px;background:linear-gradient(90deg,var(--kogane),var(--accent));border-radius:2px;margin-bottom:10px"></div>
    <div style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin-bottom:5px">
      <i class="fas fa-list-ol" style="color:var(--kogane);margin-right:8px"></i>ビートカウンター
    </div>
    <div style="font-size:13px;color:var(--text-muted)">Save the Cat の15ビートを脚本に対応付け、進捗をトラッキング</div>
  </div>

  <div style="padding:12px 16px;background:var(--bg-subtle);border:1px solid var(--border);border-radius:var(--radius-md);margin-bottom:16px;display:flex;align-items:center;gap:14px">
    <div style="flex:1">
      <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);margin-bottom:5px">進捗: ${completedCount}/${BEAT_LIST.length}ビート完了 (${pct}%)</div>
      <div style="height:8px;background:var(--bg-hover);border-radius:4px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:${pct>=100?'var(--matcha)':'linear-gradient(90deg,var(--kogane),var(--accent))'};border-radius:4px;transition:width .5s ease"></div>
      </div>
    </div>
    <button class="btn btn-ghost btn-sm" onclick="if(confirm('進捗をリセットしますか？'))resetBeatCounter()"><i class="fas fa-rotate-left"></i></button>
  </div>

  <div class="card">
    <div style="font-size:13.5px;font-weight:700;color:var(--text-primary);margin-bottom:14px;font-family:'Noto Serif JP',serif">
      <i class="fas fa-cat" style="color:var(--kogane);margin-right:7px"></i>Save the Cat — 15ビートシート
    </div>
    ${beatItems}
  </div>`;
}

function toggleBeat(beatId) {
  const beats = DB.get('sl_beat_counter', {});
  if (!beats[beatId]) beats[beatId] = {};
  beats[beatId].completed = !beats[beatId].completed;
  DB.set('sl_beat_counter', beats);
  render();
}

function saveBeatNote(beatId, val) {
  const beats = DB.get('sl_beat_counter', {});
  if (!beats[beatId]) beats[beatId] = {};
  beats[beatId].note = val;
  DB.set('sl_beat_counter', beats);
}

function resetBeatCounter() {
  DB.set('sl_beat_counter', {});
  render();
}

// ================================================================
//  新ツール: 幕バランス健康診断
// ================================================================
function renderToolActHealth() {
  return `
  <div class="article-back-btn" onclick="navigate('tools')"><i class="fas fa-arrow-left"></i> ツール一覧</div>
  <div style="background:linear-gradient(135deg,var(--kogane-bg),var(--bg-subtle));border:1px solid var(--kogane-border);border-radius:var(--radius-lg);padding:20px 24px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:80px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--kogane);opacity:0.06;pointer-events:none">幕</div>
    <div style="width:26px;height:2.5px;background:linear-gradient(90deg,var(--kogane),var(--accent));border-radius:2px;margin-bottom:10px"></div>
    <div style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin-bottom:5px">
      <i class="fas fa-stethoscope" style="color:var(--kogane);margin-right:8px"></i>幕バランス健康診断
    </div>
    <div style="font-size:13px;color:var(--text-muted)">脚本のページ数・分数・構成情報を入力して、三幕バランスと主要ビートの位置を診断します。</div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
    <div style="display:flex;flex-direction:column;gap:14px">
      <div class="card">
        <div class="card-header"><div class="card-title"><i class="fas fa-file-alt icon" style="color:var(--kogane)"></i> 作品基本情報</div></div>
        <div class="form-group">
          <label class="form-label">フォーマット</label>
          <select class="form-select" id="ah-format" onchange="ahUpdateTargets()">
            <option value="movie">映画（90〜120分 / 90〜120ページ）</option>
            <option value="drama60">TVドラマ60分（45〜60ページ）</option>
            <option value="drama45">TVドラマ45分（35〜45ページ）</option>
            <option value="short">短編映画（10〜40分）</option>
            <option value="web">ウェブドラマ（20〜30分）</option>
          </select>
        </div>
        <div class="grid-2">
          <div class="form-group">
            <label class="form-label">総ページ数</label>
            <input class="form-input" id="ah-total-pages" type="number" placeholder="110" min="1" max="300">
          </div>
          <div class="form-group">
            <label class="form-label">総分数（概算）</label>
            <input class="form-input" id="ah-total-mins" type="number" placeholder="110" min="1" max="300">
          </div>
        </div>
        <div id="ah-targets" style="font-size:11.5px;color:var(--text-muted);padding:8px 10px;background:var(--bg-subtle);border-radius:var(--radius-sm);line-height:1.9">
          目安：Act1 = 25% / Act2 = 50% / Act3 = 25%
        </div>
      </div>
      <div class="card">
        <div class="card-header"><div class="card-title"><i class="fas fa-door-open icon" style="color:var(--accent)"></i> 転換点の位置</div></div>
        <div class="form-group">
          <label class="form-label">ターニングポイント1（Act1→Act2）のページ</label>
          <input class="form-input" id="ah-tp1" type="number" placeholder="例: 25">
        </div>
        <div class="form-group">
          <label class="form-label">ミッドポイントのページ</label>
          <input class="form-input" id="ah-mp" type="number" placeholder="例: 55">
        </div>
        <div class="form-group">
          <label class="form-label">ターニングポイント2（Act2→Act3）のページ</label>
          <input class="form-input" id="ah-tp2" type="number" placeholder="例: 85">
        </div>
        <div class="form-group">
          <label class="form-label">クライマックスのページ</label>
          <input class="form-input" id="ah-climax" type="number" placeholder="例: 100">
        </div>
      </div>
      <button class="btn btn-primary" style="width:100%" onclick="runActHealth()">
        <i class="fas fa-stethoscope"></i> 幕バランスを診断する
      </button>
    </div>
    <div>
      <div class="card" style="min-height:600px;position:sticky;top:80px">
        <div class="card-header"><div class="card-title"><i class="fas fa-chart-bar icon" style="color:var(--kogane)"></i> 診断結果</div></div>
        <div id="ah-results">
          <div style="text-align:center;padding:60px 20px;color:var(--text-muted)">
            <i class="fas fa-stethoscope" style="font-size:40px;display:block;margin-bottom:14px;opacity:0.2"></i>
            <div style="font-size:13px">情報を入力して診断ボタンを押すと<br>幕バランスの分析が表示されます</div>
          </div>
        </div>
      </div>
    </div>
  </div>`;
}

function ahUpdateTargets() {
  const fmt = document.getElementById('ah-format')?.value;
  const targets = {
    movie: '映画：Act1≈25p / Act2≈55p / Act3≈30p（計110p基準）',
    drama60: 'TVドラマ60分：Act1≈12p / Act2≈30p / Act3≈12p（計54p基準）',
    drama45: 'TVドラマ45分：Act1≈10p / Act2≈22p / Act3≈8p（計40p基準）',
    short: '短編：Act1≈20% / Act2≈55% / Act3≈25%',
    web: 'ウェブドラマ：Act1≈6p / Act2≈15p / Act3≈6p（計27p基準）',
  };
  const el = document.getElementById('ah-targets');
  if (el) el.textContent = targets[fmt] || '目安：Act1 = 25% / Act2 = 50% / Act3 = 25%';
}

function runActHealth() {
  const total = parseInt(document.getElementById('ah-total-pages')?.value) || 0;
  const tp1   = parseInt(document.getElementById('ah-tp1')?.value) || 0;
  const mp    = parseInt(document.getElementById('ah-mp')?.value) || 0;
  const tp2   = parseInt(document.getElementById('ah-tp2')?.value) || 0;
  const climax= parseInt(document.getElementById('ah-climax')?.value) || 0;
  const fmt   = document.getElementById('ah-format')?.value || 'movie';

  if (!total) { toast('総ページ数を入力してください', 'error'); return; }

  const act1 = tp1;
  const act2 = tp2 - tp1;
  const act3 = total - tp2;
  const act1pct = total > 0 ? Math.round(act1/total*100) : 0;
  const act2pct = total > 0 ? Math.round(act2/total*100) : 0;
  const act3pct = total > 0 ? Math.round(act3/total*100) : 0;

  // 理想値（フォーマット別）
  const targets = { movie: {a1:25,a2:50,a3:25}, drama60:{a1:22,a2:56,a3:22}, drama45:{a1:25,a2:50,a3:25}, short:{a1:20,a2:55,a3:25}, web:{a1:22,a2:56,a3:22} };
  const target = targets[fmt] || targets.movie;
  const TOLERANCE = 6; // ±6%許容

  const checks = [];
  if (tp1 > 0) {
    const a1ok = Math.abs(act1pct - target.a1) <= TOLERANCE;
    checks.push({ label:`Act1（序幕）`, val:`${act1}p / ${act1pct}%`, ideal:`${target.a1}%前後`, ok: a1ok, tip: a1ok ? 'バランス良好' : act1pct > target.a1 + TOLERANCE ? `長すぎます（${act1pct-target.a1}%超過）。TP1をもう少し前に移動しましょう。` : `短すぎます（${target.a1-act1pct}%不足）。世界観・主人公の日常・インサイティング・インシデントが十分に描かれているか確認。` });
  }
  if (tp1 > 0 && tp2 > 0) {
    const a2ok = Math.abs(act2pct - target.a2) <= TOLERANCE;
    checks.push({ label:`Act2（本幕）`, val:`${act2}p / ${act2pct}%`, ideal:`${target.a2}%前後`, ok: a2ok, tip: a2ok ? 'バランス良好' : act2pct > target.a2 + TOLERANCE ? `長すぎます。Act2の沼にはまっている可能性。ミッドポイントの強化と「悪役の迫来」シーンを見直しましょう。` : `短すぎます。主人公の試練・成長・関係性を十分に描く場面が不足している可能性があります。` });
  }
  if (tp2 > 0) {
    const a3ok = Math.abs(act3pct - target.a3) <= TOLERANCE;
    checks.push({ label:`Act3（終幕）`, val:`${act3}p / ${act3pct}%`, ideal:`${target.a3}%前後`, ok: a3ok, tip: a3ok ? 'バランス良好' : act3pct > target.a3 + TOLERANCE ? `長すぎます。クライマックス後のデノウマンが長い可能性。「勝利を確認したら終わる」を意識。` : `短すぎます。クライマックスとデノウマンが急ぎすぎているかもしれません。主人公の変化を見せる時間を確保しましょう。` });
  }
  if (mp > 0 && total > 0) {
    const mpPct = Math.round(mp/total*100);
    const mpOk = Math.abs(mpPct - 50) <= 8;
    checks.push({ label:`ミッドポイント`, val:`${mp}p / ${mpPct}%`, ideal:`48〜52%前後`, ok: mpOk, tip: mpOk ? '理想的な位置にあります' : `${mpPct}%地点。${mpPct < 45 ? 'Act2前半が終わりすぎています。ミッドポイントをもう少し後ろに移動するか、前半の展開を充実させましょう。' : 'Act2後半が短くなっています。ミッドポイントを前に移動するか、後半の「悪役の迫来」シーンを充実させましょう。'}` });
  }
  if (climax > 0 && total > 0) {
    const climaxPct = Math.round(climax/total*100);
    const climaxOk = climaxPct >= 85 && climaxPct <= 97;
    checks.push({ label:`クライマックス`, val:`${climax}p / ${climaxPct}%`, ideal:`85〜97%前後`, ok: climaxOk, tip: climaxOk ? '理想的な位置にあります' : climaxPct < 85 ? '早すぎます。クライマックス後にページが余りすぎている可能性。終盤の展開を後ろに移動しましょう。' : 'クライマックスが最後すぎます。クライマックス後にデノウマン（解決）のための時間を確保しましょう。' });
  }

  const allOk = checks.every(c => c.ok);
  const okCount = checks.filter(c => c.ok).length;
  const score = checks.length > 0 ? Math.round(okCount/checks.length*100) : 0;
  const scoreColor = score >= 80 ? 'var(--matcha)' : score >= 50 ? 'var(--kogane)' : 'var(--accent)';

  // ビジュアルバー（全体の幕構成）
  const barHtml = total > 0 && tp1 > 0 && tp2 > 0 ? `
  <div style="margin-bottom:18px">
    <div style="font-size:11.5px;font-weight:600;color:var(--text-muted);margin-bottom:6px">幕構成ビジュアル</div>
    <div style="height:24px;border-radius:var(--radius-sm);overflow:hidden;display:flex;font-size:10px;font-weight:700;color:white">
      <div style="width:${act1pct}%;background:var(--matcha);display:flex;align-items:center;justify-content:center;min-width:${act1pct > 5 ? 0 : 0}px">A1</div>
      <div style="width:${act2pct}%;background:var(--accent);display:flex;align-items:center;justify-content:center">A2</div>
      <div style="width:${act3pct}%;background:var(--fuji);display:flex;align-items:center;justify-content:center">A3</div>
    </div>
    <div style="display:flex;justify-content:space-between;font-size:10.5px;color:var(--text-muted);margin-top:4px">
      <span>0p</span>
      ${tp1>0?`<span style="color:var(--accent)">TP1 ${tp1}p</span>`:''}
      ${mp>0?`<span style="color:var(--kogane)">MP ${mp}p</span>`:''}
      ${tp2>0?`<span style="color:var(--accent)">TP2 ${tp2}p</span>`:''}
      <span>${total}p</span>
    </div>
  </div>` : '';

  const resultsEl = document.getElementById('ah-results');
  if (!resultsEl) return;
  resultsEl.innerHTML = `
  <div style="text-align:center;margin-bottom:20px;padding:16px;background:${score>=80?'var(--matcha-bg)':score>=50?'var(--kogane-bg)':'var(--accent-bg)'};border-radius:var(--radius-md);border:1px solid ${score>=80?'var(--matcha-border)':score>=50?'var(--kogane-border)':'var(--accent-border)'}">
    <div style="font-size:42px;font-weight:700;color:${scoreColor};font-family:'Noto Serif JP',serif">${score}<span style="font-size:18px">点</span></div>
    <div style="font-size:12px;color:var(--text-muted)">幕バランス健全度（${okCount}/${checks.length}項目OK）</div>
  </div>
  ${barHtml}
  <div style="display:flex;flex-direction:column;gap:8px">
    ${checks.map(c => `
    <div style="padding:10px 12px;background:${c.ok?'var(--matcha-bg)':'var(--bg-subtle)'};border:1px solid ${c.ok?'var(--matcha-border)':'var(--border)'};border-radius:var(--radius-sm);border-left:3px solid ${c.ok?'var(--matcha)':'var(--accent)'}">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">
        <span style="font-size:12.5px;font-weight:700;color:var(--text-primary)">${c.label}</span>
        <span style="font-size:11px;color:var(--text-muted)">${c.val}</span>
        <span style="margin-left:auto;font-size:10.5px;color:var(--text-muted)">目安：${c.ideal}</span>
      </div>
      <div style="font-size:12px;color:${c.ok?'var(--matcha)':'var(--accent)'}">${c.ok?'✅ ':''}<span style="color:var(--text-secondary)">${c.tip}</span></div>
    </div>`).join('')}
  </div>
  ${allOk ? `<div class="success-box" style="margin-top:14px"><i class="fas fa-circle-check"></i><div>全ての幕バランスが理想的な範囲内です！構造として健全な脚本です。</div></div>` : ''}`;
  toast('診断完了！', 'success');
}

// ================================================================
//  新ツール: 葛藤エスカレーションプランナー
// ================================================================
function renderToolConflictEscalation() {
  return `
  <div class="article-back-btn" onclick="navigate('tools')"><i class="fas fa-arrow-left"></i> ツール一覧</div>
  <div style="background:linear-gradient(135deg,var(--accent-bg),var(--bg-subtle));border:1px solid var(--accent-border);border-radius:var(--radius-lg);padding:20px 24px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:80px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--accent);opacity:0.06;pointer-events:none">炎</div>
    <div style="width:26px;height:2.5px;background:linear-gradient(90deg,var(--accent),var(--kogane));border-radius:2px;margin-bottom:10px"></div>
    <div style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin-bottom:5px">
      <i class="fas fa-fire" style="color:var(--accent);margin-right:8px"></i>葛藤エスカレーションプランナー
    </div>
    <div style="font-size:13px;color:var(--text-muted)">主人公の目標・障害・賭けを入力し、葛藤を段階的に強化するプランを生成します。</div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
    <div style="display:flex;flex-direction:column;gap:14px">
      <div class="card">
        <div class="card-header"><div class="card-title"><i class="fas fa-bullseye icon" style="color:var(--accent)"></i> 物語の基礎設定</div></div>
        <div class="form-group">
          <label class="form-label">主人公の最終ゴール</label>
          <input class="form-input" id="ce-goal" placeholder="例：20年前の事件の真犯人を突き止める">
        </div>
        <div class="form-group">
          <label class="form-label">最大の障害（最終ボス）</label>
          <input class="form-input" id="ce-obstacle" placeholder="例：元上司が真犯人であり、現在は権力者">
        </div>
        <div class="form-group">
          <label class="form-label">主人公が失うものの最大値（賭け）</label>
          <input class="form-input" id="ce-stakes" placeholder="例：命・家族・自分が守ってきた信念">
        </div>
        <div class="form-group">
          <label class="form-label">主人公の内的欠如（ウーンド）</label>
          <input class="form-input" id="ce-wound" placeholder="例：冤罪に加担した罪悪感、信頼できない人間関係">
        </div>
        <div class="form-group">
          <label class="form-label">ジャンル</label>
          <select class="form-select" id="ce-genre">
            <option>ドラマ</option><option>サスペンス</option><option>ラブストーリー</option>
            <option>青春</option><option>アクション</option><option>コメディ</option><option>ホラー</option>
          </select>
        </div>
        <button class="btn btn-primary" style="width:100%;margin-top:6px" onclick="generateConflictPlan()">
          <i class="fas fa-fire"></i> エスカレーションプランを生成
        </button>
      </div>
    </div>
    <div>
      <div class="card" style="min-height:600px;position:sticky;top:80px">
        <div class="card-header">
          <div class="card-title"><i class="fas fa-stairs icon" style="color:var(--accent)"></i> エスカレーションプラン</div>
          <button class="btn btn-ghost btn-sm" id="ce-copy-btn" style="display:none" onclick="copyCePlan()"><i class="fas fa-copy"></i></button>
        </div>
        <div id="ce-results">
          <div style="text-align:center;padding:60px 20px;color:var(--text-muted)">
            <i class="fas fa-fire" style="font-size:40px;display:block;margin-bottom:14px;opacity:0.2"></i>
            <div style="font-size:13px">情報を入力して生成ボタンを押すと<br>葛藤エスカレーションプランが表示されます</div>
          </div>
        </div>
      </div>
    </div>
  </div>`;
}

function generateConflictPlan() {
  const goal    = document.getElementById('ce-goal')?.value.trim();
  const obstacle = document.getElementById('ce-obstacle')?.value.trim();
  const stakes  = document.getElementById('ce-stakes')?.value.trim();
  const wound   = document.getElementById('ce-wound')?.value.trim();
  const genre   = document.getElementById('ce-genre')?.value || 'ドラマ';

  if (!goal) { toast('主人公のゴールを入力してください', 'error'); return; }

  const phases = [
    {
      act: 'Act1 序幕',
      level: 1,
      color: 'var(--matcha)',
      label: '葛藤の種まき',
      desc: `主人公が「${goal || 'ゴール'}」に向けて動き出すが、最初の小さな障害に直面する。この段階では主人公はまだ「勝てる」と信じている。`,
      tips: [
        `インサイティング・インシデント：${obstacle || '障害'}の存在・予兆を示す`,
        wound ? `ウーンド（${wound}）が表れる最初の場面` : 'キャラクターの欠如が垣間見える場面',
        '観客が主人公を応援したくなる「Save the Cat」的場面',
        'ゴールの難しさを示す最初の「壁」をTPl前に置く',
      ],
    },
    {
      act: 'Act2前半',
      level: 2,
      color: 'var(--kogane)',
      label: '障害の具体化',
      desc: `新世界に入った主人公が、${obstacle || '障害'}の全貌を徐々に知る。策が一つ塞がれるたびに、より大きな代償が見えてくる。`,
      tips: [
        '最初の計画が失敗する（小さな敗北）',
        'BストーリーがAストーリーと交差し始める',
        `賭け（${stakes || '失うもの'}）の意味が深まる場面`,
        'ミッドポイントへの布石：「これで勝てる」と思わせる偽の勝利または最初の大打撃',
      ],
    },
    {
      act: 'ミッドポイント',
      level: 3,
      color: 'var(--accent)',
      label: '認識の転換',
      desc: `主人公が「自分が本当に戦っているもの」に気づく瞬間。外的なゴール（${goal}）の裏に、内的な変化の必要性が露わになる。`,
      tips: [
        '偽の勝利 or 偽の敗北のどちらかを明確に設置',
        wound ? `${wound}がより深刻な形で主人公の前に立ちはだかる` : 'キャラクターの欠如が最大の障害として浮上する',
        `${obstacle || '障害'}が単純な「敵」ではなく複雑な存在に見え始める`,
        '主人公と観客が同時に「これは難しい」と気づくターニングポイント',
      ],
    },
    {
      act: 'Act2後半',
      level: 4,
      color: 'var(--accent)',
      label: '最大の危機',
      desc: `「悪役の迫来」フェーズ。${obstacle || '最大の敵'}が反撃に出て、主人公は最も困難な状況に追い込まれる。`,
      tips: [
        stakes ? `${stakes}が実際に脅かされる場面` : '主人公が最も大切なものを失いかけるシーン',
        '主人公のライ（誤信念）が最も強く発動する場面',
        '「All is Lost（全てを失う）」シーンの直前まで追い詰める',
        '主人公が一時的に諦めるか、最悪の選択肢を考える',
      ],
    },
    {
      act: 'All is Lost → 暗闇の魂',
      level: 5,
      color: 'var(--accent)',
      label: '最低点・どん底',
      desc: `主人公が全てを失ったかに見える瞬間。${stakes || '全ての賭け'}が崩壊し、立ち直れないように見える。しかしこの暗闇こそが変容の前夜。`,
      tips: [
        `「${stakes || 'もの'}」を実際に失う or 取り返しのつかないことをしてしまう`,
        wound ? `${wound}が主人公を完全に麻痺させる瞬間` : '最大の弱点が全面に出る',
        '死（物理的・象徴的・感情的な何らかの死）の瞬間',
        '「暗闇の魂」：一人で孤独に向き合う静かな場面',
      ],
    },
    {
      act: 'Act3 クライマックス',
      level: 6,
      color: 'var(--matcha)',
      label: '変容による勝利',
      desc: `主人公が変化した自分の力でクライマックスに挑む。外的ゴール（${goal}）の達成と、内的変化（ライからトゥルースへ）が同時に起きる。`,
      tips: [
        wound ? `${wound}の克服を行動で「証明」する場面` : '内的変化を行動で体現する決定的な場面',
        `${obstacle || '最大の敵'}との最終対決`,
        '「このキャラクターがあの第一場面の自分なら、この選択はできなかった」を感じさせる決断',
        `${stakes || '全てのもの'}を犠牲にしてでも真実を選ぶ瞬間（または取り戻す瞬間）`,
      ],
    },
  ];

  const plansHtml = phases.map((ph, i) => `
  <div style="padding:14px;background:var(--bg-subtle);border:1px solid var(--border);border-radius:var(--radius-md);border-left:4px solid ${ph.color};margin-bottom:10px">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
      <div style="width:28px;height:28px;border-radius:50%;background:${ph.color};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:white;flex-shrink:0">${ph.level}</div>
      <div>
        <div style="font-size:12px;font-weight:700;color:var(--text-primary)">${ph.act}</div>
        <div style="font-size:11px;font-weight:700;color:${ph.color}">${ph.label}</div>
      </div>
    </div>
    <div style="font-size:12.5px;color:var(--text-secondary);line-height:1.7;margin-bottom:8px">${ph.desc}</div>
    <div style="font-size:11.5px;color:var(--text-muted)">
      ${ph.tips.map(t => `<div style="padding:2px 0">• ${t}</div>`).join('')}
    </div>
  </div>`).join('');

  const resultsEl = document.getElementById('ce-results');
  if (!resultsEl) return;
  window._ce_plan = phases.map(p => `[${p.act} — ${p.label}]\n${p.desc}\n• ${p.tips.join('\n• ')}`).join('\n\n');
  resultsEl.innerHTML = plansHtml;
  const copyBtn = document.getElementById('ce-copy-btn');
  if (copyBtn) copyBtn.style.display = '';
  toast('エスカレーションプラン生成完了！', 'success');
}

function copyCePlan() {
  if (window._ce_plan) {
    navigator.clipboard.writeText(window._ce_plan).then(() => toast('コピーしました', 'success'));
  }
}

// ================================================================
//  新ツール: サブテキスト変換ツール
// ================================================================
function renderToolSubtextRewriter() {
  return `
  <div class="article-back-btn" onclick="navigate('tools')"><i class="fas fa-arrow-left"></i> ツール一覧</div>
  <div style="background:linear-gradient(135deg,var(--asagi-bg),var(--bg-subtle));border:1px solid var(--asagi-border);border-radius:var(--radius-lg);padding:20px 24px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;right:20px;top:50%;transform:translateY(-50%);font-size:80px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--asagi);opacity:0.06;pointer-events:none">裏</div>
    <div style="width:26px;height:2.5px;background:linear-gradient(90deg,var(--asagi),var(--fuji));border-radius:2px;margin-bottom:10px"></div>
    <div style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin-bottom:5px">
      <i class="fas fa-comment-slash" style="color:var(--asagi);margin-right:8px"></i>サブテキスト変換ツール
    </div>
    <div style="font-size:13px;color:var(--text-muted)">直接的すぎるセリフを「オン・ザ・ノーズ」診断し、サブテキストを含む表現に変換するヒントを提供します。</div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
    <div style="display:flex;flex-direction:column;gap:14px">
      <div class="card">
        <div class="card-header"><div class="card-title"><i class="fas fa-pencil icon" style="color:var(--asagi)"></i> 診断するセリフ</div></div>
        <div class="form-group">
          <label class="form-label">直接的なセリフ（変換したいセリフ）</label>
          <textarea class="form-textarea" id="sr-dialogue" rows="4" placeholder="例：「私はあなたのことが好きです。一緒にいると嬉しいです」&#10;例：「もうこんな会社は嫌だ。辞めたい」"></textarea>
        </div>
        <div class="form-group">
          <label class="form-label">このシーンの状況・文脈</label>
          <textarea class="form-textarea" id="sr-context" rows="3" placeholder="例：職場で気になる相手と初めて二人になったとき&#10;例：上司に叱責されて廊下に出た直後"></textarea>
        </div>
        <div class="form-group">
          <label class="form-label">キャラクターが本当は言いたいこと（隠したいこと）</label>
          <input class="form-input" id="sr-true-feeling" placeholder="例：「好き」「もう限界」「あなたが必要だ」">
        </div>
        <div class="form-group">
          <label class="form-label">キャラクターの性格・ボイス</label>
          <input class="form-input" id="sr-voice" placeholder="例：内向的で不器用、照れを冗談でごまかす">
        </div>
        <button class="btn btn-primary" style="width:100%;margin-top:6px" onclick="rewriteSubtext()">
          <i class="fas fa-comment-slash"></i> サブテキストに変換する
        </button>
      </div>

      <div class="card" style="background:var(--bg-subtle)">
        <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);margin-bottom:10px"><i class="fas fa-lightbulb" style="color:var(--kogane);margin-right:5px"></i>サブテキストの7技法</div>
        ${[
          ['間接比喩', '「好き」の代わりに、相手に関わるものを大切にする行動'],
          ['話題のすり替え', '核心を避けて関係のない話をする（逃げる行動が本音を語る）'],
          ['沈黙・間', '言葉の代わりに沈黙が感情を語る（「…」「（間）」の活用）'],
          ['言葉と行動の矛盾', '「もう帰ります」と言いながらドアの前で立ち止まる'],
          ['物への執着', '大切な人の持ち物をなぜか手放せない'],
          ['アクション・タスク', '感情の代わりに何かに熱中する（コーヒーを何度も注ぐ等）'],
          ['断片化した言葉', '言いかけてやめる「あの…そういえば…いや、なんでもない」'],
        ].map(([t,d]) => `<div style="display:flex;gap:8px;padding:5px 0;border-bottom:1px solid var(--border-subtle)"><span style="font-size:11px;font-weight:700;color:var(--asagi);flex-shrink:0;min-width:90px">${t}</span><span style="font-size:11.5px;color:var(--text-secondary)">${d}</span></div>`).join('')}
      </div>
    </div>
    <div>
      <div class="card" style="min-height:500px;position:sticky;top:80px">
        <div class="card-header"><div class="card-title"><i class="fas fa-wand-magic-sparkles icon" style="color:var(--asagi)"></i> 変換結果</div></div>
        <div id="sr-results">
          <div style="text-align:center;padding:60px 20px;color:var(--text-muted)">
            <i class="fas fa-comment-slash" style="font-size:40px;display:block;margin-bottom:14px;opacity:0.2"></i>
            <div style="font-size:13px">セリフと状況を入力して<br>変換ボタンを押してください</div>
          </div>
        </div>
      </div>
    </div>
  </div>`;
}

function rewriteSubtext() {
  const dialogue    = document.getElementById('sr-dialogue')?.value.trim();
  const context     = document.getElementById('sr-context')?.value.trim();
  const trueFeeling = document.getElementById('sr-true-feeling')?.value.trim();
  const voice       = document.getElementById('sr-voice')?.value.trim();

  if (!dialogue) { toast('セリフを入力してください', 'error'); return; }

  // オン・ザ・ノーズ診断
  const emotionWords = ['好き','嫌い','嬉しい','悲しい','怖い','辛い','幸せ','寂しい','怒っている','愛している','憎い','不安','楽しい','悔しい','感謝'];
  const explainWords = ['つまり','要するに','なぜなら','ということは','だから','結局'];
  const foundEmotions = emotionWords.filter(w => dialogue.includes(w));
  const foundExplains = explainWords.filter(w => dialogue.includes(w));

  const onNoseScore = foundEmotions.length + foundExplains.length;
  const onNoseLevel = onNoseScore === 0 ? '低（サブテキストの余地あり）' : onNoseScore <= 2 ? '中（部分的に直接的）' : '高（かなりオン・ザ・ノーズ）';

  // 変換パターン生成
  const patterns = [];

  if (trueFeeling || dialogue) {
    const feeling = trueFeeling || '感情';

    // パターン1: 行動による置き換え
    patterns.push({
      technique: '行動・仕草による表現',
      icon: 'fa-hand',
      color: 'var(--asagi)',
      original: dialogue,
      rewrite: `（セリフを減らし、行動で表現する例）\n• 「${feeling}」を直接言う代わりに、相手に関わるものを無意識に触る・直す\n• 立ち去ろうとして、でも足が止まる\n${context ? `• ${context}の状況なら: 視線・手の動き・呼吸で感情を演出` : ''}`,
      hint: 'セリフをなくしてト書きだけにしてみましょう。',
    });

    // パターン2: 間接的な言葉
    patterns.push({
      technique: '間接的・迂回した言葉',
      icon: 'fa-route',
      color: 'var(--fuji)',
      original: dialogue,
      rewrite: `（「${feeling}」を直接言わない変換例）\n• 別の話題を持ち出す「そういえば…昨日、変な夢を見た」\n• 関係のないことにこだわる「このコーヒー、前より薄いね」\n${voice ? `• ${voice}らしい言い方: 本音を包む独特のキャラクター表現` : '• キャラクターの語彙・癖を使って本音を包む'}`,
      hint: '言いたいことを言わずに、何か別のことを言わせましょう。それが本音に見えるなら成功です。',
    });

    // パターン3: 沈黙と間
    patterns.push({
      technique: '沈黙・間の活用',
      icon: 'fa-ellipsis',
      color: 'var(--momo)',
      original: dialogue,
      rewrite: `（間と沈黙を使った変換例）\n[長い沈黙]\n「…そう」\n[また沈黙]\n「……今日、寒いね」\n→ 言葉が出てこないこと自体が感情を語る`,
      hint: '「……」「（間）」「（沈黙）」を使い、セリフを削ぎ落としましょう。残ったものが本音です。',
    });
  }

  const resultsEl = document.getElementById('sr-results');
  if (!resultsEl) return;

  resultsEl.innerHTML = `
  <div style="padding:12px 14px;background:${onNoseScore<=1?'var(--matcha-bg)':onNoseScore<=3?'var(--kogane-bg)':'var(--accent-bg)'};border:1px solid ${onNoseScore<=1?'var(--matcha-border)':onNoseScore<=3?'var(--kogane-border)':'var(--accent-border)'};border-radius:var(--radius-md);margin-bottom:16px">
    <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);margin-bottom:4px">オン・ザ・ノーズ診断</div>
    <div style="font-size:13px;font-weight:700;color:${onNoseScore<=1?'var(--matcha)':onNoseScore<=3?'var(--kogane)':'var(--accent)'}">レベル：${onNoseLevel}</div>
    ${foundEmotions.length>0 ? `<div style="font-size:11.5px;color:var(--text-muted);margin-top:4px">感情語：「${foundEmotions.join('・')}」を使用</div>` : ''}
    ${foundExplains.length>0 ? `<div style="font-size:11.5px;color:var(--text-muted)">説明語：「${foundExplains.join('・')}」を使用</div>` : ''}
  </div>

  <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);margin-bottom:10px">変換パターン（3つの技法）</div>
  ${patterns.map((p, i) => `
  <div style="padding:12px 14px;background:var(--bg-subtle);border:1px solid var(--border);border-radius:var(--radius-md);border-left:3px solid ${p.color};margin-bottom:10px">
    <div style="font-size:11.5px;font-weight:700;color:${p.color};margin-bottom:6px">
      <i class="fas ${p.icon}" style="margin-right:5px"></i>${i+1}. ${p.technique}
    </div>
    <div style="font-size:12px;color:var(--text-secondary);white-space:pre-line;line-height:1.7;background:white;padding:8px;border-radius:var(--radius-sm);border:1px solid var(--border);margin-bottom:8px">${p.rewrite}</div>
    <div style="font-size:11.5px;color:var(--text-muted);font-style:italic"><i class="fas fa-lightbulb" style="color:var(--kogane);margin-right:4px"></i>${p.hint}</div>
  </div>`).join('')}

  <div class="article-callout asagi" style="margin-top:8px">
    <strong>変換のゴール：</strong>このセリフを読んだ人が「この人は本当は${trueFeeling||'何かを言いたかった'}んだな」と"感じる"かどうか。
  </div>`;

  toast('変換パターン生成完了！', 'success');
}

