//  PAGE: 執筆日誌
// ================================================================
function renderJournalPage() {
  const entries = DB.get('journal_entries', []);
  const today = new Date().toISOString().slice(0,10);
  const todayEntry = entries.find(e => e.date === today);
  const streak = calcWritingStreak(entries);
  const journalSearch = State.currentTab['journal-search'] || '';
  const journalMonth = State.currentTab['journal-month'] || '';

  // フィルタリングされたエントリ
  let filteredEntries = entries.slice();
  if (journalSearch) {
    const q = journalSearch.toLowerCase();
    filteredEntries = filteredEntries.filter(e =>
      (e.body||'').toLowerCase().includes(q) ||
      (e.goal||'').toLowerCase().includes(q) ||
      (e.reflection||'').toLowerCase().includes(q) ||
      e.date.includes(q)
    );
  }
  if (journalMonth) {
    filteredEntries = filteredEntries.filter(e => e.date.startsWith(journalMonth));
  }

  // 月別リスト（フィルター用）
  const monthSet = [...new Set(entries.map(e => e.date.slice(0,7)))].sort((a,b)=>b.localeCompare(a));

  const recentEntries = filteredEntries.slice(0, 50).map(e => {
    const wc = e.wordCount || 0;
    const mood = e.mood || '😐';
    const highlightText = (text) => {
      if (!journalSearch || !text) return esc(text||'');
      const q = journalSearch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      return esc(text).replace(new RegExp(q, 'gi'), m => `<mark style="background:var(--kogane-bg);color:var(--kogane);border-radius:2px">${m}</mark>`);
    };
    return `
    <div class="card" style="padding:14px;margin-bottom:10px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">
        <div style="font-size:13px;font-weight:700;color:var(--text-primary);font-family:'Noto Serif JP',serif">
          ${e.date} <span style="font-size:16px;margin-left:6px">${mood}</span>
        </div>
        <div style="display:flex;gap:8px;align-items:center">
          ${wc > 0 ? `<span class="tag tag-matcha"><i class="fas fa-font" style="font-size:9px"></i> ${wc.toLocaleString()}字</span>` : ''}
          <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteJournalEntry('${e.id}')"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
        </div>
      </div>
      ${e.goal ? `<div style="font-size:12px;font-weight:600;color:var(--matcha);margin-bottom:5px"><i class="fas fa-bullseye" style="font-size:10px;margin-right:4px"></i>目標: ${highlightText(e.goal)}</div>` : ''}
      <div style="font-size:12.5px;color:var(--text-secondary);line-height:1.7;white-space:pre-wrap">${highlightText((e.body||'').slice(0,200))}${(e.body||'').length>200?'…':''}</div>
      ${e.reflection ? `<div style="margin-top:8px;font-size:12px;color:var(--text-muted);border-top:1px solid var(--border);padding-top:8px;font-style:italic"><i class="fas fa-comment" style="font-size:9px;margin-right:4px"></i>${highlightText(e.reflection)}</div>` : ''}
    </div>`;
  }).join('');

  // 月別統計
  const monthMap = {};
  entries.forEach(e => {
    const m = e.date.slice(0,7);
    monthMap[m] = (monthMap[m]||0) + (e.wordCount||0);
  });
  const monthStats = Object.entries(monthMap).slice(-6).map(([m, wc]) => {
    const max = Math.max(...Object.values(monthMap), 1);
    const pct = Math.round((wc/max)*100);
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:4px">
      <div style="width:32px;background:var(--bg-hover);border-radius:4px 4px 0 0;overflow:hidden;height:60px;display:flex;align-items:flex-end">
        <div style="width:100%;background:var(--matcha);border-radius:3px 3px 0 0;height:${pct}%;transition:height .3s"></div>
      </div>
      <div style="font-size:9px;color:var(--text-muted)">${m.slice(5)}月</div>
      <div style="font-size:10px;font-weight:700;color:var(--matcha)">${wc >= 1000 ? (wc/1000).toFixed(1)+'k' : wc}</div>
    </div>`;
  }).join('');

  const totalWords = entries.reduce((a, e) => a + (e.wordCount||0), 0);
  const avgWords = entries.length > 0 ? Math.round(totalWords / entries.length) : 0;

  return `
  <div class="section-header">
    <div class="section-title"><i class="fas fa-book"></i> 執筆日誌</div>
    <div class="section-desc">毎日の執筆記録・進捗・気づきを記録しましょう</div>
  </div>

  <!-- 統計バー -->
  <div class="stat-grid" style="margin-bottom:24px">
    <div class="stat-card matcha">
      <div class="stat-icon-wrap"><i class="fas fa-fire"></i></div>
      <div class="stat-value">${streak}</div>
      <div class="stat-label">連続執筆日数</div>
    </div>
    <div class="stat-card kon">
      <div class="stat-icon-wrap"><i class="fas fa-calendar-check"></i></div>
      <div class="stat-value">${entries.length}</div>
      <div class="stat-label">総記録日数</div>
    </div>
    <div class="stat-card kogane">
      <div class="stat-icon-wrap"><i class="fas fa-font"></i></div>
      <div class="stat-value">${totalWords >= 10000 ? Math.round(totalWords/1000)+'k' : totalWords.toLocaleString()}</div>
      <div class="stat-label">総執筆文字数</div>
    </div>
    <div class="stat-card beni">
      <div class="stat-icon-wrap"><i class="fas fa-chart-line"></i></div>
      <div class="stat-value">${avgWords >= 1000 ? (avgWords/1000).toFixed(1)+'k' : avgWords.toLocaleString()}</div>
      <div class="stat-label">平均文字/日</div>
    </div>
  </div>

  <div style="display:grid;grid-template-columns:1fr 340px;gap:24px">
    <!-- 左: 記録フォーム + 一覧 -->
    <div>
      <!-- 今日の記録 -->
      <div class="card" style="margin-bottom:20px">
        <div class="card-header">
          <div class="card-title"><i class="fas fa-pen icon" style="color:var(--matcha)"></i> ${today} の記録</div>
          ${todayEntry ? '<span style="font-size:11px;color:var(--matcha);font-weight:600;padding:3px 9px;background:var(--matcha-bg);border-radius:var(--radius-full)">✓ 記録済み</span>' : ''}
        </div>
        <div class="grid-2" style="margin-bottom:10px">
          <div class="form-group" style="margin-bottom:0">
            <label class="form-label">今日の目標</label>
            <input class="form-input" id="j-goal" value="${todayEntry?.goal||''}" placeholder="例：第3シーンを書ききる">
          </div>
          <div class="form-group" style="margin-bottom:0">
            <label class="form-label">執筆文字数</label>
            <input class="form-input" id="j-wordcount" type="number" value="${todayEntry?.wordCount||''}" placeholder="0">
          </div>
        </div>
        <div class="form-group">
          <label class="form-label">気分・コンディション</label>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            ${['😊','🔥','😐','😔','😤','💤','✨','🤔'].map(m =>
              `<button onclick="selectMood('${m}')" id="mood-${m}" class="btn btn-ghost btn-sm" style="font-size:18px;padding:4px 8px;${(todayEntry?.mood||'😐')===m?'background:var(--bg-hover);border-color:var(--accent)':''}">${m}</button>`
            ).join('')}
          </div>
        </div>
        <div class="form-group">
          <label class="form-label">今日の執筆メモ・進捗</label>
          <textarea class="form-textarea" id="j-body" rows="4" placeholder="今日書いた内容・気づき・詰まった点などを自由に記録...">${todayEntry?.body||''}</textarea>
        </div>
        <div class="form-group">
          <label class="form-label">振り返り・反省</label>
          <textarea class="form-textarea" id="j-reflection" rows="2" placeholder="明日に活かしたいこと...">${todayEntry?.reflection||''}</textarea>
        </div>
        <button class="btn btn-primary" onclick="saveJournalEntry()" style="width:100%">
          <i class="fas fa-floppy-disk"></i> ${todayEntry ? '更新する' : '記録を保存する'}
        </button>
      </div>

      <!-- 過去の記録 -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
        <div style="font-size:15px;font-weight:700;color:var(--text-primary);font-family:'Noto Serif JP',serif">
          <i class="fas fa-clock-rotate-left" style="color:var(--momo);margin-right:8px"></i>過去の記録
          <span style="font-size:12px;font-weight:400;color:var(--text-muted);margin-left:6px">(${filteredEntries.length} / ${entries.length}件)</span>
        </div>
      </div>
      <!-- 日誌検索バー -->
      <div style="display:flex;gap:8px;margin-bottom:12px">
        <div style="flex:1;position:relative">
          <i class="fas fa-search" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:12px;pointer-events:none"></i>
          <input class="form-input" id="journal-search" value="${esc(journalSearch)}" placeholder="過去の日誌を全文検索…"
            style="padding-left:30px;font-size:12.5px;height:34px"
            oninput="setJournalSearch(this.value)">
        </div>
        <select class="form-select" style="font-size:12px;height:34px;padding:0 10px;width:auto" onchange="setJournalMonth(this.value)">
          <option value="">全期間</option>
          ${monthSet.map(m => {
            const [yr,mo] = m.split('-');
            return `<option value="${m}" ${journalMonth===m?'selected':''}>${yr}年${parseInt(mo)}月</option>`;
          }).join('')}
        </select>
        ${journalSearch||journalMonth ? `<button class="btn btn-ghost btn-sm" onclick="setJournalSearch('');setJournalMonth('')"><i class="fas fa-xmark"></i></button>` : ''}
      </div>
      ${filteredEntries.length === 0 ?
        `<div style="text-align:center;padding:40px;color:var(--text-muted);background:var(--bg-subtle);border-radius:var(--radius-md);border:2px dashed var(--border)">
          <i class="fas fa-search" style="font-size:32px;display:block;margin-bottom:10px;opacity:0.3"></i>
          ${journalSearch||journalMonth ? '条件に一致する記録がありません' : 'まだ記録がありません。今日の執筆を記録しましょう！'}
        </div>`
        : recentEntries}
    </div>

    <!-- 右: グラフ・カレンダー -->
    <div style="display:flex;flex-direction:column;gap:16px">
      <!-- 月別執筆量グラフ -->
      ${Object.keys(monthMap).length > 0 ? `
      <div class="card" style="padding:0;overflow:hidden">
        <div style="padding:12px 16px;border-bottom:1px solid var(--border);background:var(--bg-subtle);font-size:13px;font-weight:600;color:var(--text-primary);font-family:'Noto Serif JP',serif">
          <i class="fas fa-chart-bar" style="color:var(--matcha);margin-right:6px"></i>月別執筆量
        </div>
        <div style="padding:16px;display:flex;align-items:flex-end;gap:8px;height:100px">
          ${monthStats}
        </div>
      </div>` : ''}

      <!-- 執筆習慣カレンダー -->
      <div class="card" style="padding:0;overflow:hidden">
        <div style="padding:12px 16px;border-bottom:1px solid var(--border);background:var(--bg-subtle);font-size:13px;font-weight:600;color:var(--text-primary);font-family:'Noto Serif JP',serif">
          <i class="fas fa-calendar" style="color:var(--asagi);margin-right:6px"></i>執筆カレンダー
        </div>
        <div style="padding:14px">
          ${renderJournalCalendar(entries)}
        </div>
      </div>

      <!-- ヒント -->
      <div class="writing-tip-box">
        <div class="writing-tip-title"><i class="fas fa-lightbulb"></i> 継続のコツ</div>
        <div class="writing-tip-body">「毎日1行」を目標に設定すると継続しやすくなります。完璧な1時間より、不完全な10分の方が長期的に意味があります。日誌は振り返りのためのもので、評価されるためのものではありません。</div>
      </div>
    </div>
  </div>`;
}

function calcWritingStreak(entries) {
  if (entries.length === 0) return 0;
  const dates = [...new Set(entries.map(e => e.date))].sort().reverse();
  if (!dates.length) return 0;
  const today = new Date().toISOString().slice(0,10);
  let streak = 0;
  let cur = new Date(today);
  for (const d of dates) {
    const dc = cur.toISOString().slice(0,10);
    if (d === dc) {
      streak++;
      cur.setDate(cur.getDate()-1);
    } else break;
  }
  return streak;
}

function renderJournalCalendar(entries) {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month+1, 0).getDate();
  const entryDates = new Set(entries.map(e => e.date));
  const days = ['日','月','火','水','木','金','土'];

  let html = `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;font-size:10px;text-align:center;margin-bottom:6px">`;
  html += days.map(d => `<div style="color:var(--text-muted);font-weight:600;padding:2px 0">${d}</div>`).join('');
  html += '</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px">';

  for (let i = 0; i < firstDay; i++) {
    html += `<div></div>`;
  }
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const hasEntry = entryDates.has(dateStr);
    const isToday = dateStr === today.toISOString().slice(0,10);
    html += `<div style="aspect-ratio:1;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:10px;font-weight:${isToday?'700':'400'};
      ${hasEntry ? 'background:var(--matcha);color:white' : isToday ? 'background:var(--accent);color:white' : 'color:var(--text-muted)'}">${d}</div>`;
  }
  html += '</div>';
  html += `<div style="margin-top:8px;font-size:10.5px;color:var(--text-muted);display:flex;gap:10px;align-items:center">
    <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:var(--matcha);border-radius:50%;display:inline-block"></span>執筆記録あり</span>
    <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:var(--accent);border-radius:50%;display:inline-block"></span>今日</span>
  </div>`;
  return html;
}

let _selectedMood = '😐';
function selectMood(mood) {
  _selectedMood = mood;
  ['😊','🔥','😐','😔','😤','💤','✨','🤔'].forEach(m => {
    const btn = $(`#mood-${m}`);
    if (btn) btn.style.background = m === mood ? 'var(--bg-hover)' : '';
    if (btn) btn.style.borderColor = m === mood ? 'var(--accent)' : '';
  });
}

function saveJournalEntry() {
  const entries = DB.get('journal_entries', []);
  const today = new Date().toISOString().slice(0,10);
  const body = $('#j-body')?.value?.trim();
  const goal = $('#j-goal')?.value?.trim();
  const wordCount = parseInt($('#j-wordcount')?.value||'0') || 0;
  const reflection = $('#j-reflection')?.value?.trim();
  const mood = _selectedMood || '😐';

  const existing = entries.findIndex(e => e.date === today);
  const entry = { id: existing >= 0 ? entries[existing].id : uid(), date: today, body, goal, wordCount, reflection, mood, updatedAt: new Date().toISOString() };

  if (existing >= 0) entries[existing] = entry;
  else entries.unshift(entry);

  DB.set('journal_entries', entries);
  toast('執筆日誌を保存しました', 'success');
  navigate('journal');
}

function deleteJournalEntry(id) {
  openModal(
    `<i class="fas fa-trash" style="color:var(--accent)"></i> 記録を削除`,
    `<p style="color:var(--text-secondary)">この記録を削除しますか？元に戻せません。</p>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-danger" onclick="confirmDeleteJournalEntry('${id}')"><i class="fas fa-trash"></i> 削除</button>`
  );
}

function setJournalSearch(q) {
  State.currentTab['journal-search'] = q;
  navigate('journal');
}

function setJournalMonth(m) {
  State.currentTab['journal-month'] = m;
  navigate('journal');
}

function confirmDeleteJournalEntry(id) {
  const entries = DB.get('journal_entries', []).filter(e => e.id !== id);
  DB.set('journal_entries', entries);
  closeModal();
  toast('削除しました', 'info');
  navigate('journal');
}

function bindJournalPage() {
  const today = new Date().toISOString().slice(0,10);
  const entries = DB.get('journal_entries', []);
  const todayEntry = entries.find(e => e.date === today);
  _selectedMood = todayEntry?.mood || '😐';
}

// ================================================================
//  PAGE: キャラクター名辞典
// ================================================================
function renderNameDictPage() {
  const names = DB.get('namedict', []);
  const ndFilter = DB.get('namedict_filter', { search: '', category: 'all', view: 'grouped' });
  const viewMode = ndFilter.view || 'grouped';
  const categories = ['主人公','敵役','脇役','助演','その他'];
  const catCounts = {};
  categories.forEach(c => { catCounts[c] = names.filter(n => n.category === c).length; });

  const CAT_STYLES = {
    '主人公':  { color:'var(--accent)',  bg:'var(--accent-bg)',  border:'var(--accent-border)',  icon:'fa-star' },
    '敵役':    { color:'var(--momo)',    bg:'var(--momo-bg)',    border:'var(--momo-border)',    icon:'fa-mask' },
    '脇役':    { color:'var(--asagi)',   bg:'var(--asagi-bg)',   border:'var(--asagi-border)',   icon:'fa-user' },
    '助演':    { color:'var(--kogane)',  bg:'var(--kogane-bg)', border:'var(--kogane-border)', icon:'fa-user-group' },
    'その他':  { color:'var(--text-muted)', bg:'var(--bg-hover)', border:'var(--border)',  icon:'fa-ellipsis' },
  };

  // フィルタリング
  let filtered = names.slice();
  if (ndFilter.search) {
    const q = ndFilter.search.toLowerCase();
    filtered = filtered.filter(n =>
      (n.name||'').toLowerCase().includes(q) ||
      (n.kana||'').toLowerCase().includes(q) ||
      (n.tags||'').toLowerCase().includes(q) ||
      (n.note||'').toLowerCase().includes(q)
    );
  }
  if (ndFilter.category && ndFilter.category !== 'all') {
    filtered = filtered.filter(n => (n.category||'その他') === ndFilter.category);
  }

  const makeCard = (n) => {
    const cs = CAT_STYLES[n.category||'その他'] || CAT_STYLES['その他'];
    return `
    <div class="card" style="position:relative;transition:all .15s" onmouseover="this.style.boxShadow='0 2px 12px rgba(0,0,0,.08)'" onmouseout="this.style.boxShadow=''">
      <div style="position:absolute;left:0;top:0;bottom:0;width:3px;background:${cs.color};border-radius:var(--radius-md) 0 0 var(--radius-md)"></div>
      <div style="padding-left:4px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
          <div style="display:flex;align-items:center;gap:8px">
            <div style="width:30px;height:30px;border-radius:50%;background:${cs.bg};border:1px solid ${cs.border};display:flex;align-items:center;justify-content:center;font-size:12px;color:${cs.color}">
              <i class="fas ${cs.icon}"></i>
            </div>
            <div>
              <div style="font-size:15px;font-weight:700;color:var(--text-primary);font-family:'Noto Serif JP',serif">${esc(n.name)}</div>
              ${n.kana ? `<div style="font-size:11px;color:var(--text-muted)">${esc(n.kana)}</div>` : ''}
            </div>
          </div>
          <div style="display:flex;gap:3px;align-items:center">
            <span style="font-size:9.5px;padding:2px 8px;background:${cs.bg};border:1px solid ${cs.border};border-radius:var(--radius-full);color:${cs.color};font-weight:600">${esc(n.category||'その他')}</span>
            <button class="btn btn-ghost btn-icon btn-sm" onclick="openEditNameDict('${n.id}')"><i class="fas fa-pen" style="font-size:10px"></i></button>
            <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteNameDict('${n.id}')"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
          </div>
        </div>
        ${n.tags ? `<div style="margin-bottom:5px;display:flex;flex-wrap:wrap;gap:4px">${n.tags.split(',').map(t => t.trim() ? `<span class="tag tag-gray" style="font-size:10px">${esc(t.trim())}</span>` : '').join('')}</div>` : ''}
        ${n.note ? `<div style="font-size:12px;color:var(--text-secondary);line-height:1.6;border-top:1px solid var(--border);padding-top:5px;margin-top:3px">${esc(n.note.slice(0,80))}${n.note.length>80?'…':''}</div>` : ''}
        ${n.project ? `<div style="font-size:10px;color:var(--text-muted);margin-top:5px"><i class="fas fa-film" style="font-size:9px;margin-right:3px"></i>${esc(n.project)}</div>` : ''}
      </div>
    </div>`;
  };

  let gridContent = '';
  if (filtered.length === 0) {
    gridContent = `<div style="text-align:center;padding:48px;color:var(--text-muted);grid-column:1/-1;border:2px dashed var(--border);border-radius:var(--radius-md)">
      <i class="fas fa-spell-check" style="font-size:32px;display:block;margin-bottom:10px;opacity:0.3"></i>
      ${ndFilter.search || ndFilter.category !== 'all' ? '条件に一致するキャラクターが見つかりません' : '名前辞典はまだ空です。キャラクターを追加しましょう。'}
    </div>`;
  } else if (viewMode === 'grouped' && (!ndFilter.search && ndFilter.category === 'all')) {
    // グループ表示
    gridContent = categories.map(cat => {
      const catNames = filtered.filter(n => (n.category||'その他') === cat);
      if (catNames.length === 0) return '';
      const cs = CAT_STYLES[cat] || CAT_STYLES['その他'];
      return `
      <div style="grid-column:1/-1;margin-bottom:4px;padding:8px 12px;background:${cs.bg};border:1px solid ${cs.border};border-radius:var(--radius-md);display:flex;align-items:center;gap:8px;margin-top:8px">
        <i class="fas ${cs.icon}" style="color:${cs.color};font-size:13px"></i>
        <span style="font-size:13px;font-weight:700;color:${cs.color};font-family:'Noto Serif JP',serif">${cat}</span>
        <span style="font-size:11px;background:${cs.color};color:white;padding:1px 8px;border-radius:var(--radius-full)">${catNames.length}人</span>
      </div>
      ${catNames.map(n => makeCard(n)).join('')}`;
    }).join('');
  } else {
    gridContent = filtered.map(n => makeCard(n)).join('');
  }

  return `
  <!-- ヘッダー -->
  <div style="background:linear-gradient(135deg,var(--kon-bg,#eef3fb),var(--bg-subtle));border:1px solid var(--kon-border,#b8cee8);border-radius:var(--radius-lg);padding:18px 22px;margin-bottom:20px;position:relative;overflow:hidden">
    <div style="position:absolute;right:16px;top:50%;transform:translateY(-50%);font-size:60px;font-weight:900;font-family:'Noto Serif JP',serif;color:var(--kon-lt,#1d3d6b);opacity:0.05">名</div>
    <div style="display:flex;align-items:center;justify-content:space-between">
      <div>
        <h2 style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin:0"><i class="fas fa-spell-check" style="color:var(--kon-lt);margin-right:10px"></i>キャラクター名辞典</h2>
        <div style="font-size:12.5px;color:var(--text-muted);margin-top:3px">登場人物の名前・読み・メモを一元管理（${names.length}件登録済み）</div>
      </div>
      <button class="btn btn-primary" onclick="openAddNameDict()"><i class="fas fa-plus"></i> 新規追加</button>
    </div>
  </div>

  <!-- カテゴリ統計バー -->
  <div style="display:flex;gap:6px;margin-bottom:16px;flex-wrap:wrap">
    <button class="btn btn-sm ${ndFilter.category==='all'?'btn-primary':'btn-ghost'}" onclick="DB.set('namedict_filter',{...DB.get('namedict_filter',{search:'',category:'all',view:'grouped'}),category:'all'});render()">
      <i class="fas fa-users" style="font-size:10px"></i> すべて (${names.length})
    </button>
    ${categories.filter(c => catCounts[c] > 0).map(c => {
      const cs = CAT_STYLES[c] || CAT_STYLES['その他'];
      const active = ndFilter.category === c;
      return `<button class="btn btn-sm ${active?'btn-primary':'btn-ghost'}" style="${active?'':'border-color:'+cs.border+';color:'+cs.color}" onclick="DB.set('namedict_filter',{...DB.get('namedict_filter',{search:'',category:'all',view:'grouped'}),category:'${c}'});render()">
        <i class="fas ${cs.icon}" style="font-size:10px"></i> ${c} (${catCounts[c]})
      </button>`;
    }).join('')}
  </div>

  <!-- 検索・表示切替 -->
  ${names.length > 0 ? `
  <div style="display:flex;gap:8px;margin-bottom:16px;align-items:center;flex-wrap:wrap">
    <div style="position:relative;flex:1;min-width:180px;max-width:360px">
      <i class="fas fa-search" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:var(--text-muted);font-size:12px"></i>
      <input class="form-input" id="namedict-search" style="padding-left:30px" placeholder="名前・タグ・メモで検索..." value="${esc(ndFilter.search||'')}"
        oninput="const f=DB.get('namedict_filter',{search:'',category:'all',view:'grouped'});f.search=this.value;DB.set('namedict_filter',f);filterNameDictLive(this.value)">
    </div>
    <div style="display:flex;gap:4px">
      <button class="btn btn-sm ${viewMode==='grouped'?'btn-primary':'btn-ghost'}" onclick="const f=DB.get('namedict_filter',{search:'',category:'all',view:'grouped'});f.view='grouped';DB.set('namedict_filter',f);render()" title="グループ表示">
        <i class="fas fa-layer-group" style="font-size:11px"></i>
      </button>
      <button class="btn btn-sm ${viewMode==='grid'?'btn-primary':'btn-ghost'}" onclick="const f=DB.get('namedict_filter',{search:'',category:'all',view:'grouped'});f.view='grid';DB.set('namedict_filter',f);render()" title="グリッド表示">
        <i class="fas fa-grip" style="font-size:11px"></i>
      </button>
      <button class="btn btn-sm ${viewMode==='list'?'btn-primary':'btn-ghost'}" onclick="const f=DB.get('namedict_filter',{search:'',category:'all',view:'grouped'});f.view='list';DB.set('namedict_filter',f);render()" title="リスト表示">
        <i class="fas fa-list" style="font-size:11px"></i>
      </button>
    </div>
  </div>` : ''}

  <div class="project-grid" id="namedict-grid">${gridContent}</div>`;
}

function filterNameDictLive(q) {
  const f = DB.get('namedict_filter', { search: '', category: 'all', view: 'grouped' });
  f.search = q;
  DB.set('namedict_filter', f);
  render();
}

function openAddNameDict() {
  const projects = DB.getProjects().map(p => `<option>${esc(p.title)}</option>`).join('');
  openModal(
    `<i class="fas fa-plus" style="color:var(--kon-lt)"></i> 名前を追加`,
    `<div class="form-group"><label class="form-label">名前 <span style="color:var(--accent)">*</span></label><input class="form-input" id="nd-name" placeholder="例：木村 拓也"></div>
     <div class="grid-2">
       <div class="form-group"><label class="form-label">読み（ひらがな）</label><input class="form-input" id="nd-kana" placeholder="例：きむら たくや"></div>
       <div class="form-group"><label class="form-label">カテゴリー</label>
         <select class="form-select" id="nd-cat">
           <option>主人公</option><option>敵役</option><option>脇役</option><option>助演</option><option>その他</option>
         </select>
       </div>
     </div>
     <div class="form-group"><label class="form-label">タグ（カンマ区切り）</label><input class="form-input" id="nd-tags" placeholder="例：刑事, 男性, 30代"></div>
     <div class="form-group"><label class="form-label">関連作品</label><select class="form-select" id="nd-project"><option value="">未選択</option>${projects}</select></div>
     <div class="form-group"><label class="form-label">メモ・説明</label><textarea class="form-textarea" id="nd-note" rows="2" placeholder="このキャラクターについてのメモ"></textarea></div>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-primary" onclick="addNameDict()"><i class="fas fa-plus"></i> 追加</button>`
  );
}

function addNameDict() {
  const name = $('#nd-name')?.value?.trim();
  if (!name) { toast('名前は必須です', 'error'); return; }
  const entry = {
    id: uid(), name,
    kana: $('#nd-kana')?.value?.trim() || '',
    category: $('#nd-cat')?.value || 'その他',
    tags: $('#nd-tags')?.value?.trim() || '',
    project: $('#nd-project')?.value || '',
    note: $('#nd-note')?.value?.trim() || '',
    createdAt: new Date().toISOString(),
  };
  const names = DB.get('namedict', []);
  names.unshift(entry);
  DB.set('namedict', names);
  closeModal();
  toast('追加しました', 'success');
  navigate('namedict');
}

function openEditNameDict(id) {
  const names = DB.get('namedict', []);
  const n = names.find(x => x.id === id);
  if (!n) return;
  const projects = DB.getProjects().map(p => `<option ${p.title===n.project?'selected':''}>${esc(p.title)}</option>`).join('');
  openModal(
    `<i class="fas fa-pen" style="color:var(--kon-lt)"></i> 名前を編集`,
    `<div class="form-group"><label class="form-label">名前</label><input class="form-input" id="nd-edit-name" value="${esc(n.name)}"></div>
     <div class="grid-2">
       <div class="form-group"><label class="form-label">読み</label><input class="form-input" id="nd-edit-kana" value="${esc(n.kana||'')}"></div>
       <div class="form-group"><label class="form-label">カテゴリー</label>
         <select class="form-select" id="nd-edit-cat">
           ${['主人公','敵役','脇役','助演','その他'].map(c => `<option ${c===n.category?'selected':''}>${c}</option>`).join('')}
         </select>
       </div>
     </div>
     <div class="form-group"><label class="form-label">タグ</label><input class="form-input" id="nd-edit-tags" value="${esc(n.tags||'')}"></div>
     <div class="form-group"><label class="form-label">関連作品</label><select class="form-select" id="nd-edit-project"><option value="">未選択</option>${projects}</select></div>
     <div class="form-group"><label class="form-label">メモ</label><textarea class="form-textarea" id="nd-edit-note" rows="2">${esc(n.note||'')}</textarea></div>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-primary" onclick="saveEditNameDict('${id}')">保存</button>`
  );
}

function saveEditNameDict(id) {
  const names = DB.get('namedict', []);
  const idx = names.findIndex(x => x.id === id);
  if (idx < 0) return;
  names[idx] = { ...names[idx],
    name: $('#nd-edit-name')?.value?.trim() || names[idx].name,
    kana: $('#nd-edit-kana')?.value?.trim() || '',
    category: $('#nd-edit-cat')?.value || 'その他',
    tags: $('#nd-edit-tags')?.value?.trim() || '',
    project: $('#nd-edit-project')?.value || '',
    note: $('#nd-edit-note')?.value?.trim() || '',
  };
  DB.set('namedict', names);
  closeModal();
  toast('更新しました', 'success');
  navigate('namedict');
}

function deleteNameDict(id) {
  openModal(
    `<i class="fas fa-trash" style="color:var(--accent)"></i> 名前を削除`,
    `<p style="color:var(--text-secondary)">この名前の記録を削除しますか？</p>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-danger" onclick="confirmDeleteNameDict('${id}')">削除</button>`
  );
}

function confirmDeleteNameDict(id) {
  const names = DB.get('namedict', []).filter(x => x.id !== id);
  DB.set('namedict', names);
  closeModal();
  toast('削除しました', 'info');
  navigate('namedict');
}

function filterNameDict(q) {
  const cards = $$('#namedict-grid .card');
  cards.forEach(card => {
    const text = card.textContent;
    card.style.display = !q || text.includes(q) ? '' : 'none';
  });
}

function bindNameDictPage() {}

// ================================================================
//  PAGE: 世界観設計
// ================================================================
function renderWorldBuildingPage() {
  const wbTab = DB.get('wb_active_tab', 'main');
  const wb = DB.get('worldbuilding', {
    title: '',
    era: '',
    setting: '',
    rules: '',
    geography: '',
    culture: '',
    politics: '',
    technology: '',
    magic: '',
    history: '',
    conflicts: '',
    glossary: [],
    factions: [],
    timeline: [],
  });

  const glossaryHtml = (wb.glossary || []).map((g, i) => `
    <div style="display:flex;align-items:flex-start;gap:8px;padding:8px 0;border-bottom:1px solid var(--border)">
      <div style="flex:0 0 100px;font-size:12.5px;font-weight:700;color:var(--kon-lt);font-family:'Noto Serif JP',serif">${esc(g.term)}</div>
      <div style="flex:1;font-size:12.5px;color:var(--text-secondary);line-height:1.6">${esc(g.def)}</div>
      <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteWbGlossary(${i})"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
    </div>`).join('');

  const fields = [
    { id:'title',      label:'世界観タイトル',   placeholder:'例：近未来の新東京',         rows:1 },
    { id:'era',        label:'時代・時期設定',    placeholder:'例：2045年、AIが人権を獲得した時代', rows:1 },
    { id:'setting',    label:'舞台・場所',         placeholder:'例：海面上昇後の東京。高層都市と水上スラムが並立する', rows:2 },
    { id:'rules',      label:'世界のルール（物理法則・超自然）', placeholder:'例：特定の感情を持つ者だけが「境界」を越えられる', rows:2 },
    { id:'geography',  label:'地理・地図',         placeholder:'例：三つの島に分かれた都市構造。北島は富裕層、南島は労働者層', rows:2 },
    { id:'culture',    label:'文化・習慣・宗教',   placeholder:'例：死者の日は年に一度全市民が白い仮面を着けて外出する', rows:2 },
    { id:'politics',   label:'政治・権力構造',     placeholder:'例：三つの財閥が都市を分割支配。警察は財閥傭兵が担当', rows:2 },
    { id:'technology', label:'科学技術・魔法体系', placeholder:'例：記憶を「書き換え」できるナノマシン技術が普及している', rows:2 },
    { id:'history',    label:'重要な歴史・出来事', placeholder:'例：30年前の「大分断」で旧東京が三分割された', rows:2 },
    { id:'conflicts',  label:'内在する葛藤・矛盾', placeholder:'例：AI市民権vs人間優位主義の対立が社会の根底にある', rows:2 },
  ];

  return `
  <!-- ヘッダー -->
  <div style="background:linear-gradient(135deg,var(--asagi-bg),var(--bg-subtle));border:1px solid var(--asagi-border);border-radius:var(--radius-lg);padding:18px 22px;margin-bottom:18px;position:relative;overflow:hidden">
    <div style="position:absolute;right:16px;top:50%;transform:translateY(-50%);font-size:60px;font-weight:900;font-family:'Noto Serif JP',serif;color:var(--asagi);opacity:0.05">世</div>
    <div style="display:flex;align-items:center;justify-content:space-between">
      <div>
        <h2 style="font-size:20px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary);margin:0"><i class="fas fa-globe" style="color:var(--asagi);margin-right:10px"></i>世界観設計ノート</h2>
        <div style="font-size:12.5px;color:var(--text-muted);margin-top:3px">作品の舞台・世界観・設定を詳細に設計・記録します</div>
      </div>
      <button class="btn btn-primary" onclick="saveWorldBuilding()"><i class="fas fa-floppy-disk"></i> 保存</button>
    </div>
  </div>

  <!-- タブナビ -->
  <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:18px">
    ${[
      { id:'main',     label:'基本設定',  icon:'fa-earth-asia' },
      { id:'society',  label:'社会・政治', icon:'fa-landmark' },
      { id:'factions', label:'勢力・組織', icon:'fa-shield-halved' },
      { id:'timeline', label:'歴史・年表', icon:'fa-timeline' },
      { id:'glossary', label:'用語集',     icon:'fa-book' },
    ].map(t => `<button class="btn btn-sm ${wbTab===t.id?'btn-primary':'btn-ghost'}" onclick="DB.set('wb_active_tab','${t.id}');render()">
      <i class="fas ${t.icon}" style="font-size:10px"></i> ${t.label}
    </button>`).join('')}
  </div>

  ${wbTab === 'main' ? `
  <div style="display:grid;grid-template-columns:1fr 340px;gap:24px">
    <div>
      <div class="card" style="margin-bottom:16px">
        <div class="card-header"><div class="card-title"><i class="fas fa-earth-asia icon" style="color:var(--asagi)"></i> 世界設定の基本</div></div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">
          ${fields.slice(0,2).map(f => `
            <div class="form-group">
              <label class="form-label">${f.label}</label>
              <input class="form-input" id="wb-${f.id}" value="${esc(wb[f.id]||'')}" placeholder="${f.placeholder}">
            </div>`).join('')}
        </div>
        ${fields.slice(2).map(f => `
          <div class="form-group">
            <label class="form-label">${f.label}</label>
            <textarea class="form-textarea" id="wb-${f.id}" rows="${f.rows}" placeholder="${f.placeholder}">${esc(wb[f.id]||'')}</textarea>
          </div>`).join('')}
      </div>
    </div>

    <div style="display:flex;flex-direction:column;gap:16px">
      <!-- 用語集（サイドバー） -->
      <div class="card">
        <div class="card-header">
          <div class="card-title"><i class="fas fa-book icon" style="color:var(--kon-lt)"></i> 用語集</div>
          <button class="btn btn-primary btn-sm" onclick="openAddWbGlossary()"><i class="fas fa-plus"></i></button>
        </div>
        ${(wb.glossary||[]).length === 0 ?
          `<div style="text-align:center;padding:24px;color:var(--text-muted);font-size:12.5px">用語を追加しましょう</div>`
          : `<div style="max-height:300px;overflow-y:auto">${glossaryHtml}</div>`}
      </div>
      <!-- ヒント -->
      <div class="card">
        <div class="card-title" style="margin-bottom:10px"><i class="fas fa-lightbulb icon" style="color:var(--kogane)"></i> 世界観構築のコツ</div>
        <div style="font-size:12px;color:var(--text-secondary);line-height:1.9">
          <div>🌍 「見える世界」と「見えないルール」を分けて考える</div>
          <div>⚡ 内在する矛盾・葛藤が物語を生む</div>
          <div>🔬 設定は物語に使う分だけ深掘りする</div>
          <div>📚 固有名詞は読者が覚えやすい数に絞る</div>
          <div>🗺️ 地図・年表があると整合性が取りやすい</div>
        </div>
      </div>
    </div>
  </div>` : ''}

  ${wbTab === 'society' ? `
  <div class="card">
    <div class="card-title" style="margin-bottom:16px"><i class="fas fa-landmark icon" style="color:var(--asagi)"></i> 社会・政治・経済設定</div>
    ${[
      { id:'social_structure', label:'社会構造・階級', placeholder:'例：貴族・平民・奴隷の3層構造。貴族は全人口の3%だが国富の80%を支配', rows:2 },
      { id:'economy', label:'経済・通貨・交易', placeholder:'例：魔石が通貨。北部は鉱業、南部は農業に依存。海上交易ルートが要塞化されている', rows:2 },
      { id:'law', label:'法律・司法制度', placeholder:'例：魔法師は特別裁判所に従う。一般市民は12人制陪審員制度', rows:2 },
      { id:'religion', label:'宗教・信仰体系', placeholder:'例：太陽神と月神の二神教。神殿が国政に強い影響力を持つ', rows:2 },
      { id:'education', label:'教育・知識の伝達', placeholder:'例：文字は貴族のみ学べる。口伝の伝承が一般民衆の文化を支える', rows:2 },
      { id:'military', label:'軍事・治安組織', placeholder:'例：王国軍5万人。国境守備隊は独自の自治権を持つ', rows:2 },
    ].map(f => `
    <div class="form-group">
      <label class="form-label">${f.label}</label>
      <textarea class="form-textarea" id="wbs-${f.id}" rows="${f.rows}" placeholder="${f.placeholder}" onblur="saveWbExtra('${f.id}',this.value)">${esc(wb[f.id]||'')}</textarea>
    </div>`).join('')}
    <button class="btn btn-primary" onclick="saveWbSociety()"><i class="fas fa-floppy-disk"></i> 保存</button>
  </div>` : ''}

  ${wbTab === 'factions' ? renderWbFactionsTab(wb) : ''}
  ${wbTab === 'timeline' ? renderWbTimelineTab(wb) : ''}

  ${wbTab === 'glossary' ? `
  <div class="card">
    <div class="card-header">
      <div class="card-title"><i class="fas fa-book icon" style="color:var(--kon-lt)"></i> 世界観用語集・固有名詞</div>
      <button class="btn btn-primary btn-sm" onclick="openAddWbGlossary()"><i class="fas fa-plus"></i> 追加</button>
    </div>
    ${(wb.glossary||[]).length === 0 ?
      `<div style="text-align:center;padding:40px;color:var(--text-muted)"><i class="fas fa-book" style="font-size:32px;display:block;margin-bottom:12px;opacity:0.2"></i>まだ用語が登録されていません</div>` :
      `<div>
        ${(wb.glossary||[]).map((g, i) => `
        <div style="display:flex;align-items:flex-start;gap:8px;padding:10px 0;border-bottom:1px solid var(--border)">
          <div style="flex:0 0 120px;font-size:13px;font-weight:700;color:var(--kon-lt);font-family:'Noto Serif JP',serif">${esc(g.term)}</div>
          <div style="flex:1;font-size:12.5px;color:var(--text-secondary);line-height:1.6">${esc(g.def)}</div>
          <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteWbGlossary(${i})"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
        </div>`).join('')}
      </div>`}
  </div>` : ''}`;
}

function renderWbFactionsTab(wb) {
  const factions = wb.factions || [];
  const FACTION_COLORS = ['var(--accent)','var(--fuji)','var(--momo)','var(--asagi)','var(--kogane)','var(--matcha)'];
  return `
  <div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <div style="font-size:14px;font-weight:600;color:var(--text-primary)"><i class="fas fa-shield-halved" style="color:var(--asagi);margin-right:8px"></i>勢力・組織一覧 (${factions.length})</div>
      <button class="btn btn-primary btn-sm" onclick="openAddWbFaction()"><i class="fas fa-plus"></i> 勢力を追加</button>
    </div>
    ${factions.length === 0 ?
      `<div style="text-align:center;padding:60px;color:var(--text-muted);border:2px dashed var(--border);border-radius:var(--radius-md)">
        <i class="fas fa-shield-halved" style="font-size:32px;display:block;margin-bottom:12px;opacity:0.2"></i>
        まだ勢力・組織が登録されていません
      </div>` :
      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px">
        ${factions.map((f, i) => {
          const col = FACTION_COLORS[i % FACTION_COLORS.length];
          return `
          <div class="card" style="border-top:3px solid ${col}">
            <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
              <div style="font-size:15px;font-weight:700;font-family:'Noto Serif JP',serif;color:var(--text-primary)">${esc(f.name)}</div>
              <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteWbFaction(${i})"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
            </div>
            ${f.type ? `<div style="font-size:11px;padding:2px 8px;background:var(--bg-hover);border-radius:var(--radius-full);color:${col};border:1px solid ${col}33;display:inline-block;margin-bottom:6px">${esc(f.type)}</div>` : ''}
            ${f.desc ? `<div style="font-size:12.5px;color:var(--text-secondary);line-height:1.6;margin-bottom:6px">${esc(f.desc)}</div>` : ''}
            ${f.goal ? `<div style="font-size:11.5px;color:var(--text-muted)"><strong>目的：</strong>${esc(f.goal)}</div>` : ''}
            ${f.leader ? `<div style="font-size:11.5px;color:var(--text-muted)"><strong>リーダー：</strong>${esc(f.leader)}</div>` : ''}
          </div>`;
        }).join('')}
      </div>`}
  </div>`;
}

function renderWbTimelineTab(wb) {
  const timeline = [...(wb.timeline || [])].sort((a,b) => (a.year||0) - (b.year||0));
  return `
  <div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
      <div style="font-size:14px;font-weight:600;color:var(--text-primary)"><i class="fas fa-timeline" style="color:var(--asagi);margin-right:8px"></i>歴史・年表 (${timeline.length}件)</div>
      <button class="btn btn-primary btn-sm" onclick="openAddWbTimeline()"><i class="fas fa-plus"></i> 出来事を追加</button>
    </div>
    ${timeline.length === 0 ?
      `<div style="text-align:center;padding:60px;color:var(--text-muted);border:2px dashed var(--border);border-radius:var(--radius-md)">
        <i class="fas fa-timeline" style="font-size:32px;display:block;margin-bottom:12px;opacity:0.2"></i>
        まだ歴史的出来事が登録されていません
      </div>` :
      `<div style="position:relative;padding-left:24px">
        <div style="position:absolute;left:8px;top:0;bottom:0;width:2px;background:var(--asagi-border)"></div>
        ${timeline.map((e, i) => `
        <div style="position:relative;margin-bottom:16px">
          <div style="position:absolute;left:-20px;top:6px;width:10px;height:10px;border-radius:50%;background:var(--asagi);border:2px solid white;box-shadow:0 0 0 2px var(--asagi-border)"></div>
          <div class="card" style="padding:12px 14px">
            <div style="display:flex;justify-content:space-between;align-items:flex-start">
              <div>
                <span style="font-size:11px;font-weight:700;color:var(--asagi)">${esc(String(e.year||'?'))}年</span>
                <div style="font-size:13.5px;font-weight:700;color:var(--text-primary);margin-top:2px">${esc(e.event)}</div>
              </div>
              <button class="btn btn-ghost btn-icon btn-sm" onclick="deleteWbTimeline(${i})"><i class="fas fa-trash" style="font-size:10px;color:var(--accent)"></i></button>
            </div>
            ${e.desc ? `<div style="font-size:12.5px;color:var(--text-secondary);line-height:1.6;margin-top:5px">${esc(e.desc)}</div>` : ''}
            ${e.impact ? `<div style="font-size:11.5px;color:var(--text-muted);margin-top:4px"><i class="fas fa-bolt" style="font-size:9px;color:var(--kogane);margin-right:3px"></i>影響: ${esc(e.impact)}</div>` : ''}
          </div>
        </div>`).join('')}
      </div>`}
  </div>`;
}

function saveWbSociety() {
  const ids = ['social_structure','economy','law','religion','education','military'];
  const wb = DB.get('worldbuilding', { glossary: [] });
  ids.forEach(id => {
    const el = document.getElementById(`wbs-${id}`);
    if (el) wb[id] = el.value.trim();
  });
  DB.set('worldbuilding', wb);
  toast('社会・政治設定を保存しました', 'success');
}

function saveWbExtra(field, value) {
  const wb = DB.get('worldbuilding', { glossary: [] });
  wb[field] = value;
  DB.set('worldbuilding', wb);
}

function openAddWbFaction() {
  openModal(
    `<i class="fas fa-shield-halved" style="color:var(--asagi)"></i> 勢力・組織を追加`,
    `<div class="form-group"><label class="form-label">名称 <span style="color:var(--accent)">*</span></label><input class="form-input" id="wbf-name" placeholder="例：暁の騎士団"></div>
     <div class="form-group"><label class="form-label">種類</label>
       <select class="form-select" id="wbf-type">
         <option>国家</option><option>組織</option><option>宗教団体</option><option>犯罪組織</option><option>反乱勢力</option><option>商会・ギルド</option><option>その他</option>
       </select>
     </div>
     <div class="form-group"><label class="form-label">説明・特徴</label><textarea class="form-textarea" id="wbf-desc" rows="3" placeholder="この勢力の特徴・信条・歴史"></textarea></div>
     <div class="grid-2">
       <div class="form-group"><label class="form-label">目的・目標</label><input class="form-input" id="wbf-goal" placeholder="例：旧王朝の復活"></div>
       <div class="form-group"><label class="form-label">リーダー</label><input class="form-input" id="wbf-leader" placeholder="例：影の皇帝ヴァロン"></div>
     </div>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-primary" onclick="addWbFaction()"><i class="fas fa-plus"></i> 追加</button>`
  );
}

function addWbFaction() {
  const name = $('#wbf-name')?.value?.trim();
  if (!name) { toast('名称を入力してください', 'error'); return; }
  const wb = DB.get('worldbuilding', { glossary: [], factions: [], timeline: [] });
  if (!wb.factions) wb.factions = [];
  wb.factions.push({
    name, type: $('#wbf-type')?.value || 'その他',
    desc: $('#wbf-desc')?.value?.trim() || '',
    goal: $('#wbf-goal')?.value?.trim() || '',
    leader: $('#wbf-leader')?.value?.trim() || '',
  });
  DB.set('worldbuilding', wb);
  closeModal(); toast('勢力を追加しました', 'success'); render();
}

function deleteWbFaction(idx) {
  const wb = DB.get('worldbuilding', { glossary: [], factions: [] });
  if (!wb.factions) return;
  wb.factions.splice(idx, 1);
  DB.set('worldbuilding', wb);
  toast('削除しました', 'success'); render();
}

function openAddWbTimeline() {
  openModal(
    `<i class="fas fa-timeline" style="color:var(--asagi)"></i> 歴史的出来事を追加`,
    `<div class="grid-2">
       <div class="form-group"><label class="form-label">年（数字）</label><input class="form-input" id="wbt-year" type="number" placeholder="例：-500（マイナスは過去）"></div>
       <div class="form-group"><label class="form-label">出来事の名前 <span style="color:var(--accent)">*</span></label><input class="form-input" id="wbt-event" placeholder="例：大分断の日"></div>
     </div>
     <div class="form-group"><label class="form-label">詳細説明</label><textarea class="form-textarea" id="wbt-desc" rows="3" placeholder="この出来事の詳細・背景"></textarea></div>
     <div class="form-group"><label class="form-label">現在への影響</label><input class="form-input" id="wbt-impact" placeholder="例：この事件が現在の南北対立の根本原因になっている"></div>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-primary" onclick="addWbTimeline()"><i class="fas fa-plus"></i> 追加</button>`
  );
}

function addWbTimeline() {
  const year = parseInt($('#wbt-year')?.value);
  const event = $('#wbt-event')?.value?.trim();
  if (!event) { toast('出来事の名前を入力してください', 'error'); return; }
  const wb = DB.get('worldbuilding', { glossary: [], factions: [], timeline: [] });
  if (!wb.timeline) wb.timeline = [];
  wb.timeline.push({
    year: isNaN(year) ? 0 : year, event,
    desc: $('#wbt-desc')?.value?.trim() || '',
    impact: $('#wbt-impact')?.value?.trim() || '',
  });
  DB.set('worldbuilding', wb);
  closeModal(); toast('出来事を追加しました', 'success'); render();
}

function deleteWbTimeline(idx) {
  const wb = DB.get('worldbuilding', { glossary: [], timeline: [] });
  if (!wb.timeline) return;
  wb.timeline.splice(idx, 1);
  DB.set('worldbuilding', wb);
  toast('削除しました', 'success'); render();
}

function saveWorldBuilding() {
  const fields = ['title','era','setting','rules','geography','culture','politics','technology','history','conflicts'];
  const wb = DB.get('worldbuilding', { glossary: [] });
  fields.forEach(f => {
    const el = $(`#wb-${f}`);
    if (el) wb[f] = el.value.trim();
  });
  DB.set('worldbuilding', wb);
  toast('世界観設計を保存しました', 'success');
}

function openAddWbGlossary() {
  openModal(
    `<i class="fas fa-plus" style="color:var(--kon-lt)"></i> 用語を追加`,
    `<div class="form-group"><label class="form-label">用語・固有名詞 <span style="color:var(--accent)">*</span></label><input class="form-input" id="wbg-term" placeholder="例：境界石"></div>
     <div class="form-group"><label class="form-label">説明</label><textarea class="form-textarea" id="wbg-def" rows="3" placeholder="例：二つの世界の境界に存在する古代の石柱。特定の血筋を持つ者にのみ反応する"></textarea></div>`,
    `<button class="btn btn-secondary" onclick="closeModal()">キャンセル</button>
     <button class="btn btn-primary" onclick="addWbGlossary()">追加</button>`
  );
}

function addWbGlossary() {
  const term = $('#wbg-term')?.value?.trim();
  const def = $('#wbg-def')?.value?.trim();
  if (!term) { toast('用語を入力してください', 'error'); return; }
  const wb = DB.get('worldbuilding', { glossary: [] });
  if (!wb.glossary) wb.glossary = [];
  wb.glossary.push({ term, def });
  DB.set('worldbuilding', wb);
  closeModal();
  toast('用語を追加しました', 'success');
  navigate('worldbuilding');
}

function deleteWbGlossary(idx) {
  const wb = DB.get('worldbuilding', { glossary: [] });
  if (!wb.glossary) return;
  wb.glossary.splice(idx, 1);
  DB.set('worldbuilding', wb);
  toast('削除しました', 'info');
  navigate('worldbuilding');
}

