  if (!b) return;
  const scratches = DB.get('inspiration_scratches', []);
  scratches.unshift({ id: uid(), title: 'ブックマークから', body: b.content,
    type: '着想', tags: ['bookmark'], pinned: false, createdAt: new Date().toISOString() });
